 nodes=$WF2N$[{"parameters":{"url":"=https://lead-studio-9gnl.onrender.com/api/leads/queue","sendQuery":true,"queryParameters":{"parameters":[{"name":"limit","value":"100"},{"name":"dialCode","value":"91"}]},"sendHeaders":true,"headerParameters":{"parameters":[{"name":"Authorization","value":"=Bearer {{ $('🔐 Login LeadStudio').first().json.accessToken }}"}]},"options":{"response":{"response":{"neverError":true,"responseFormat":"json"}},"timeout":15000}},"id":"02f01a6f-cd4f-4255-a00f-cc486f4b73a5","name":"⏰ GET NO_ANSWER India (vencidos, Asterisk)","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[-20224,-2992],"disabled":true},{"parameters":{"jsCode":"// Reactiva leads NO_ANSWER cuyo nextFollowUpAt ya pasó -> los vuelve a poner\n// disponibles para que el GET Queue (status=NOT_CONTACTED) los recoja.\n// FIX: el filtro ?status=NO_ANSWER de la API no es confiable (mismo bug que\n// el filtro de country), así que acá se valida el status real del lead\n// antes de reactivar — nunca reactivar algo que no está en NO_ANSWER.\nconst now = new Date();\nconst leads = ($input.first().json.leads) || [];\nconst due = leads.filter(l =>\n  l.status === 'NO_ANSWER' &&\n  l.nextFollowUpAt &&\n  new Date(l.nextFollowUpAt) <= now\n);\nconst skipped = leads.filter(l => l.nextFollowUpAt && new Date(l.nextFollowUpAt) <= now && l.status !== 'NO_ANSWER');\nif (skipped.length) {\n  console.log('⚠️ Omitidos (status ya no es NO_ANSWER):', skipped.map(l => `${l.id}:${l.status}`).join(', '));\n}\nconsole.log('⏰', due.length, 'leads NO_ANSWER vencidos para reactivar (de', leads.length, 'total recibidos)');\nreturn due.map(l => ({ json: { lead_id: l.id } }));"},"id":"23f33ff1-c718-47ed-9c61-5ef68fad9e20","name":"🔁 Filtrar Vencidos India (Asterisk)","type":"n8n-nodes-base.code","typeVersion":2,"position":[-19984,-2992],"disabled":true},{"parameters":{"method":"PATCH","url":"=https://lead-studio-9gnl.onrender.com/api/leads/{{ $json.lead_id }}","sendHeaders":true,"headerParameters":{