console.log('⏰ Nepal —', due.length, 'leads NO_ANSWER vencidos para reactivar (de', leads.length, 'total recibidos)');\nreturn due.map(l => ({ json: { lead_id: l.id } }));"},"id":"c84e534b-ab94-4dd8-9ad3-6631a08a909d","name":"🔁 Filtrar Vencidos Nepal (Asterisk)","type":"n8n-nodes-base.code","typeVersion":2,"position":[-19984,-2832],"disabled":true},{"parameters":{"method":"PATCH","url":"=https://lead-studio-9gnl.onrender.com/api/leads/{{ $json.lead_id }}","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Authorization","value":"=Bearer {{ $('🔐 Login LeadStudio').first().json.accessToken }}"}]},"sendBody":true,"specifyBody":"json","jsonBody":"={\n  \"status\": \"NOT_CONTACTED\"\n}","options":{"response":{"response":{"neverError":true,"responseFormat":"json"}},"timeout":15000}},"id":"882fa5a0-6551-47ba-be0f-af8abd2a1b25","name":"♻️ Reactivar → NOT_CONTACTED Nepal (Asterisk)","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[-19744,-2832],"disabled":true},{"parameters":{"url":"=https://lead-studio-9gnl.onrender.com/api/leads/queue","sendQuery":true,"queryParameters":{"parameters":[{"name":"limit","value":"100"},{"name":"country","value":"IN"},{"name":"status","value":"NO_ANSWER"}]},"sendHeaders":true,"headerParameters":{"parameters":[{"name":"Authorization","value":"=Bearer {{ $('🔐 Login LeadStudio').first().json.accessToken }}"}]},"options":{"response":{"response":{"neverError":true,"responseFormat":"json"}},"timeout":15000}},"id":"95fe2c0a-8352-4be6-b05b-9a3e82dcd363","name":"⏰ GET NO_ANSWER India (vencidos, Stringee)","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[-20288,-1232],"disabled":true},{"parameters":{"jsCode":"// Reactiva leads NO_ANSWER cuyo nextFollowUpAt ya pasó -> los vuelve a poner\n// disponibles para que el GET Queue (status=NOT_CONTACTED) los recoja.\nconst now = new Date();\nconst leads = ($input.first().json.leads) || [];\nconst due = leads.filter(l => l.nextFollowUpAt && new Date(l.nextFollowUpAt) <=