"// Lee wf2_provider_config (MySQL). Fail-open: si falta tabla/fila,\n// ese proveedor queda HABILITADO por defecto.\nconst rows = $input.all().map(i => i.json).filter(r => r && r.provider);\n\nfunction isEnabled(providerName) {\n  const row = rows.find(r => String(r.provider).toLowerCase() === providerName);\n  if (!row) return true;\n  return Number(row.enabled) === 1;\n}\n\nconst asterisk_enabled = isEnabled('asterisk');\nconst stringee_enabled = isEnabled('stringee');\nconsole.log('🔀 Providers activos —', 'Asterisk:', asterisk_enabled, '| Stringee:', stringee_enabled);\nreturn [{ json: { asterisk_enabled, stringee_enabled } }];\n"},"id":"60aaac1b-c376-422c-a2ae-bbace25e77a3","name":"⚙️ Calcular Providers Activos1","type":"n8n-nodes-base.code","typeVersion":2,"position":[-22336,-1024],"disabled":true},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":2},"conditions":[{"id":"cond-token","leftValue":"={{ $json.accessToken }}","rightValue":"","operator":{"type":"string","operation":"notEquals"}}],"combinator":"and"},"options":{}},"id":"f569f0cf-9b55-4dc6-9dc4-f348bf00f4f8","name":"✅ Token OK?1","type":"n8n-nodes-base.if","typeVersion":2.2,"position":[-21568,-1072],"disabled":true},{"parameters":{"jsCode":"const resp = $('🔐 Login LeadStudio').item.json;\nconsole.error('❌ WF2: Login a LeadStudio falló', JSON.stringify(resp));\nreturn [{ json: { error: true, message: 'LeadStudio auth failed', response: resp } }];\n"},"id":"be69eac2-fca6-4705-89d1-d3991cc5ab57","name":"❌ Log Auth Error1","type":"n8n-nodes-base.code","typeVersion":2,"position":[-21344,-704],"disabled":true},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"strict","version":2},"conditions":[{"id":"cond-asterisk-on","leftValue":"={{ $('⚙️ Calcular Providers Activos1').item.json.asterisk_enabled }}","rightValue":true,"operator":{"type":"boolean","operation":"true","singleValue":true}}],"combinator":"and"},"options":{}},"id":"ea3a772c-c592-4f03-a440-311b9e456de1","name":"🔀 Asterisk Habilitado?1","type":"n8n-nodes-base.if","typeVersion":2.2,"position":[-20912,-2576],"disabled":true},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"loose","version":1},"conditions":[{"id":"cond-stringee-on","leftValue":"={{ $('⚙️ Calcular Providers Activos1').item.json.stringee_enabled }}","rightValue":true,"operator":{"type":"boolean","operation":"true","singleValue":true}}],"combinator":"and"},"options":{}},"id":"c7b776ff-11b5-4c8e-9612-ffe1a35f7687","name":"🔀 Stringee Habilitado?1","type":"n8n-nodes-base.if","typeVersion":2.2,"position":[-20864,-1472],"disabled":true},{"parameters":{"jsCode":"console.log('⏸️ Asterisk DESACTIVADO por wf2_provider_config — ciclo omitido');\nreturn [{ json: { skipped: true, provider: 'asterisk', at: new Date().toISOString() } }];"},"id":"c9e609e0-ae68-49ca-8b87-62726cdc3e03","name":"⏸️ Asterisk Desactivado (log)1","type":"n8n-nodes-base.code","typeVersion":2,"position":[-20768,-2208],"disabled":true},{"parameters":{"jsCode":"console.log('⏸️ Stringee DESACTIVADO por wf2_provider_config — ciclo omitido');\nreturn [{ json: { skipped: true, provider: 'stringee', at: new Date().toISOString() } }];"},"id":"748ca062-d92f-4a63-925f-ca63b4665791","name":"⏸️ Stringee Desactivado (log)1","type":"n8n-nodes-base.code","typeVersion":2,"position":[-20496,-1232],"disabled":true},{"parameters":{"content":"### 🔀 Switch de Proveedores + Follow-up automático (API LeadStudio)\nLee `wf2_provider_config` (MySQL) 1 vez por ciclo. Login LeadStudio se hace UNA sola vez; TODOS los nodos que necesitan el token lo referencian con:\n`{{ $('🔐 Login LeadStudio1').first().json.accessToken }}`\n\n**Listo para llamar:** `status === 'NOT_CONTACTED'`.\n\n**Ciclo de reintentos NO_ANSWER (Asterisk, SIP 603/408/486):**\nintento 1 → +2h → intento 2 → +3h → intento 3 (fin ciclo) →\nciclo 1 fin → +2 días hábiles → ciclo 2 fin → +3 días hábiles → ciclo 3 fin → **CLOSED**\n\nAntes de cada lectura de cola, un branch aparte reactiva (PATCH → NOT_CONTACTED) los leads NO_ANSWER cuyo `nextFollowUpAt` ya venció — así el GET Queue normal los vuelve a recoger.\n\n⚠️ **Stringee no tiene este ciclo todavía**: el worker solo confirma que la llamada se disparó (job_id), no si contestó — eso llega después por webhook a otro workflow. Por ahora Stringee solo marca ACTIVE/UNREACHABLE.\n\n⚠️ Si activas Asterisk + Stringee a la vez para India, ambas ramas leen el mismo GET /queue?country=IN en paralelo — ventana de milisegundos donde ambas podrían tomar el mismo lead. Mismo riesgo que ya existía con los 2 WF2 separados.","height":380,"width":520,"color":4},"id":"d0d3d6ff-323f-4a42-bf75-fd8e5ad06546","name":"🧭 Nota — Switch de Proveedores1","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[-22816,-1504],"disabled":true},{"parameters":{"url":"=https://lead-studio-9gnl.onrender.com/api/leads/queue","sendQuery":true,"queryParameters":{"parameters":[{"name":"limit","value":"50"},{"name":"dialCode","value":"91"},{"name":"status"}]},"sendHeaders":true,"headerParameters":{"parameters":[{"name":"Authorization","value":"=Bearer {{ $json.accessToken }}"}]},"options":{"response":{"response":{"neverError":true,"responseFormat":"json"}},"timeout":15000}},"id":"ea353ab0-8d64-4aee-a885-13103f11bb6e","name":"📞 GET Queue India (Asterisk)1","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[-19872,-2432],"disabled":true},{"parameters":{"url":"=https://lead-studio-9gnl.onrender.com/api/leads/queue","sendQuery":true,"queryParameters":{"parameters":[{"name":"limit","value":"50"},{"name":"dialCode","value":"977"}]},"sendHeaders":true,"headerParameters":{"parameters":[{"name":"Authorization","value":"=Bearer {{ $json.accessToken }}"}]},"options":{"response":{"response":{"neverError":true,"responseFormat":"json"}},"timeout":15000}},"id":"0d21ca64-67d7-4ea0-a725-f808d1782dd3","name":"📞 GET Queue Nepal (Asterisk)1","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[-19872,-2192],"disabled":true},{"parameters":{"jsCode":"// Normaliza leads de LeadStudio. Filtro primario: dialCode en el GET Queue.\n// Filtro secundario (defensa): detecta país por el TELÉFONO, por si algún\n// lead viene mal clasificado o el filtro de la API falla.\nconst EXPECTED = 'india';\n\nconst PREFIX_MAP = [\n  { prefix: '977', country: 'nepal' },   // el más largo primero\n  { prefix: '91',  country: 'india' }\n];\nconst CODE_MAP = { NP: 'nepal', IN: 'india', NEPAL: 'nepal', INDIA: 'india' };\n\nfunction detectCountry(l) {\n  const raw = String(l.phone || '').trim();\n  const digits = raw.replace(/[^0-9]/g, '');\n  if (raw.startsWith('+') || digits.length >= 11) {\n    const hit = PREFIX_MAP.find(m => digits.startsWith(m.prefix));\n    if (hit) return hit.country;\n  }\n  const code = String(l.countryCode || l.country || '').trim().toUpperCase();\n  return CODE_MAP[code] || null;\n}\n\nconst leads = ($input.first().json.leads) || [];\nconst out = [];\nconst rejected = [];\n\nfor (const l of leads) {\n  const detected = detectCountry(l);\n  if (detected !== EXPECTED) {\n    rejected.push({ id: l.id, phone: l.phone, detected });\n    continue;\n  }\n  out.push({ json: {\n    lead_id: l.id,\n    full_name: l.name,\n    phone: l.phone,\n    country: detected,\n    language: String(l.language || 'hi').trim().toLowerCase(),\n    status: String(l.status || '').trim().toUpperCase(),\n    call_attempts: Number(l.attempts || 0),\n    doNotCall: !!l.doNotCall,\n    _source_country: EXPECTED\n  }});\n}\n\nconsole.log(`🏷️ Normalizar ${EXPECTED}: ${out.length} OK | ${rejected.length} descartados (otro país)`,\n  JSON.stringify(rejected).slice(0, 400));\nreturn out;"},"id":"37e8f596-dda2-41e8-9c5e-a8d30e27cddd","name":"🏷️ Normalizar India (Asterisk)1","type":"n8n-nodes-base.code","typeVersion":2,"position":[-19632,-2432],"disabled":true},{"parameters":{"jsCode":"// Normaliza leads de LeadStudio. Filtro primario: dialCode en el GET Queue.\n// Filtro secundario (defensa): detecta país por el TELÉFONO, por si algún\n// lead viene mal clasificado o el filtro de la API falla.\nconst EXPECTED = 'nepal';\n\nconst PREFIX_MAP = [\n  { prefix: '977', country: 'nepal' },   // el más largo primero\n  { prefix: '91',  country: 'india' }\n];\nconst CODE_MAP = { NP: 'nepal', IN: 'india', NEPAL: 'nepal', INDIA: 'india' };\n\nfunction detectCountry(l) {\n  const raw = String(l.phone || '').trim();\n  const digits = raw.replace(/[^0-9]/g, '');\n  if (raw.startsWith('+') || digits.length >= 11) {\n    const hit = PREFIX_MAP.find(m => digits.startsWith(m.prefix));\n    if (hit) return hit.country;\n  }\n  const code = String(l.countryCode || l.country || '').trim().toUpperCase();\n  return CODE_MAP[code] || null;\n}\n\nconst leads = ($input.first().json.leads) || [];\nconst out = [];\nconst rejected = [];\n\nfor (const l of leads) {\n  const detected = detectCountry(l);\n  if (detected !== EXPECTED) {\n    rejected.push({ id: l.id, phone: l.phone, detected });\n    continue;\n  }\n  out.push({ json: {\n    lead_id: l.id,\n    full_name: l.name,\n    phone: l.phone,\n    country: detected,\n    language: String(l.language || 'hi').trim().toLowerCase(),\n    status: String(l.status || '').trim().toUpperCase(),\n    call_attempts: Number(l.attempts || 0),\n    doNotCall: !!l.doNotCall,\n    _source_country: EXPECTED\n  }});\n}\n\nconsole.log(`🏷️ Normalizar ${EXPECTED}: ${out.length} OK | ${rejected.length} descartados (otro país)`,\n  JSON.stringify(rejected).slice(0, 400));\nreturn out;"},"id":"05fe3ba8-621f-4e03-b5c2-d8465337b276","name":"🏷️ Normalizar Nepal (Asterisk)1","type":"n8n-nodes-base.code","typeVersion":2,"position":[-19632,-2192],"disabled":true},{"parameters":{},"id":"c8d40b1c-f4d8-4845-a45d-f5cce8249aba","name":"🔀 Merge India + Nepal (Asterisk)1","type":"n8n-nodes-base.merge","typeVersion":3,"position":[-19392,-2304],"disabled":true},{"parameters":{"jsCode":"// MULTI-PAIS — India + Nepal (API LeadStudio). Batch SEPARADO por país + dedup.\n// CRITERIO DE LISTO PARA LLAMAR: status === 'NOT_CONTACTED'.\nconst COUNTRY_CFG = {\n  india: { dialPrefix: '+91', language: 'hi', batchSize: 10,\n    agent_id: 'agent_5701kramx550e3qs2tm11661b48p',\n    agent_phone_number_id: 'phnum_7801kyktmabxembteqce884tanb6' },\n  nepal: { dialPrefix: '+977', language: 'hi', batchSize: 10,\n    agent_id: 'agent_7601m209ntj3fyrbg0dcq6w507yq',\n    agent_phone_number_id: 'phnum_7801kyktmabxembteqce884tanb6' }\n};\n\nfunction normalizePhone(rawPhone, countryKey) {\n  let p = String(rawPhone || '').replace(/[^0-9+]/g, '');\n  if (!p) return '';\n  const cfg = COUNTRY_CFG[countryKey];\n  if (p.startsWith('+')) return p;\n  const prefixDigits = cfg.dialPrefix.replace('+', '');\n  if (p.startsWith(prefixDigits) && p.length > prefixDigits.length + 6) return '+' + p;\n  return cfg.dialPrefix + p;\n}\n\nconst buckets = Object.fromEntries(Object.keys(COUNTRY_CFG).map(k => [k, []]));\nconst seen = new Set();\nconst skipped = [];\n\nfor (const item of $input.all()) {\n  const r = { ...(item.json || {}) };\n  if (!r.lead_id) continue;\n  if (seen.has(r.lead_id)) { skipped.push({ lead_id: r.lead_id, reason: 'duplicado' }); continue; }\n  seen.add(r.lead_id);\n\n  if (r.doNotCall) { skipped.push({ lead_id: r.lead_id, reason: 'doNotCall' }); continue; }\n  if (r.status !== 'NOT_CONTACTED') { skipped.push({ lead_id: r.lead_id, reason: `status=${r.status}` }); continue; }\n\n  const cfg = COUNTRY_CFG[r.country];\n  if (!cfg) { skipped.push({ lead_id: r.lead_id, reason: `country no soportado: ${r.country}` }); continue; }\n\n  const phone = normalizePhone(r.phone, r.country);\n  if (!/^\\+[1-9]\\d{7,14}$/.test(phone)) { skipped.push({ lead_id: r.lead_id, reason: `bad phone: '${r.phone}'` }); continue; }\n\n  if (!phone.startsWith(cfg.dialPrefix)) {\n    skipped.push({ lead_id: r.lead_id, reason: `prefijo ${phone.slice(0,4)} no es de ${r.country}` });\n    continue;\n  }\n\n  buckets[r.country].push({ json: {\n    ...r, phone,\n    _agent_id: cfg.agent_id,\n    _agent_phone_number_id: cfg.agent_phone_number_id,\n    language: r.language || cfg.language\n  }});\n}\n\nconst out = [];\nfor (const [country, list] of Object.entries(buckets)) {\n  const take = list.slice(0, COUNTRY_CFG[country].batchSize);\n  console.log(`⚙️ Asterisk ${country}: ${list.length} elegibles → ${take.length} al batch`);\n  out.push(...take);\n}\nconsole.log('⏭️ skipped:', skipped.length, JSON.stringify(skipped).slice(0, 500));\nreturn out;"},"id":"89502d69-3e89-4aff-8ea6-8dc3c7c170d7","name":"⚙️ Select Batch + Country Route (Asterisk)1","type":"n8n-nodes-base.code","typeVersion":2,"position":[-19152,-2304],"disabled":true},{"parameters":{"method":"POST","url":"https://api.elevenlabs.io/v1/convai/sip-trunk/outbound-call","authentication":"genericCredentialType","genericAuthType":"=httpHeaderAuth","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Content-Type","value":"application/json"},{"name":"xi-api-key","value":"sk_79048a9776812db4416e5c690d0c047132d565fee7d43acd"}]},"sendBody":true,"specifyBody":"json","jsonBody":"={\n  \"agent_id\": \"{{ $('⚙️ Select Batch + Country Route (Asterisk)1').item.json._agent_id }}\",\n  \"agent_phone_number_id\": \"{{ $('⚙️ Select Batch + Country Route (Asterisk)1').item.json._agent_phone_number_id }}\",\n  \"to_number\": \"{{ $('⚙️ Select Batch + Country Route (Asterisk)1').item.json.phone }}\",\n  \"conversation_initiation_client_data\": {\n    \"conversation_config_override\": {\n      \"agent\": { \"language\": \"{{ $('⚙️ Select Batch + Country Route (Asterisk)1').item.json.language }}\" }\n    },\n    \"dynamic_variables\": {\n      \"lead_id\": \"{{ $('⚙️ Select Batch + Country Route (Asterisk)1').item.json.lead_id }}\",\n      \"full_name\": \"{{ $('⚙️ Select Batch + Country Route (Asterisk)1').item.json.full_name }}\",\n      \"phone\": \"{{ $('⚙️ Select Batch + Country Route (Asterisk)1').item.json.phone }}\",\n      \"country\": \"{{ $('⚙️ Select Batch + Country Route (Asterisk)1').item.json.country }}\",\n      \"language\": \"{{ $('⚙️ Select Batch + Country Route (Asterisk)1').item.json.language }}\",\n      \"is_followup\": \"false\",\n      \"call_attempts\": \"{{ Number($('⚙️ Select Batch + Country Route (Asterisk)1').item.json.call_attempts || 0) + 1 }}\"\n    }\n  }\n}","options":{"batching":{"batch":{"batchSize":5,"batchInterval":0}},"response":{"response":{"fullResponse":true,"neverError":true,"responseFormat":"json"}},"timeout":600000}},"id":"ef686792-1868-4c9e-9fb0-26ebcddb68b1","name":"📞 POST → ElevenLabs Dial (Asterisk)1","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[-18672,-2304],"credentials":{"httpHeaderAuth":{"id":"ui7o7nfbbbmdISf2","name":"Header Auth account"}},"disabled":true,"continueOnFail":true,"onError":"continueRegularOutput"},{"parameters":{"jsCode":"const items = $input.all();\nconst leads = $('⚙️ Select Batch + Country Route (Asterisk)1').all();\nconst now = new Date().toISOString();\nconst nowDate = new Date();\n\nconst NO_ANSWER_CODES = ['603', '408', '486'];\n\nfunction addHours(date, h) {\n  return new Date(date.getTime() + h * 60 * 60 * 1000).toISOString();\n}\n\nfunction addBusinessDays(date, days) {\n  const result = new Date(date.getTime());\n  let added = 0;\n  while (added < days) {\n    result.setDate(result.getDate() + 1);\n    const dow = result.getDay();\n    if (dow !== 0 && dow !== 6) added++;\n  }\n  return result.toISOString();\n}\n\nreturn items.map((item, i) => {\n  const resp = item.json || {};\n  const lead = (leads[i] || leads[0]).json;\n  const body = resp.body ?? resp;\n  const conversationId = body.conversation_id || '';\n  const success = body.success === true;\n  const message = String(body.message || '');\n\n  const sipMatch = message.match(/SIP\\s*(\\d{3})/i) || message.match(/\\b(\\d{3})\\b/);\n  const sipCode = sipMatch ? sipMatch[1] : null;\n  const isNoAnswer = sipCode && NO_ANSWER_CODES.includes(sipCode);\n\n  const attempts = Number(lead.call_attempts || 0) + 1;\n\n  let status, last_call_status, notes, nextFollowUpAt = null;\n\n  if (success && conversationId) {\n    status = 'CONTACTED';\n    last_call_status = 'ANSWERED';\n    notes = '🟢 Call connected: ' + conversationId;\n  } else if (isNoAnswer) {\n    last_call_status = 'NO_ANSWER_SIP_' + sipCode;\n\n    const posInCycle = ((attempts - 1) % 3) + 1;\n    const cycle = Math.ceil(attempts / 3);\n\n    if (posInCycle === 1) {\n      status = 'NO_ANSWER';\n      nextFollowUpAt = addHours(nowDate, 2);\n      notes = `🟡 No answer (SIP ${sipCode}) — attempt ${attempts} (cycle ${cycle}, pos 1/3) — next in 2h`;\n    } else if (posInCycle === 2) {\n      status = 'NO_ANSWER';\n      nextFollowUpAt = addHours(nowDate, 3);\n      notes = `🟡 No answer (SIP ${sipCode}) — attempt ${attempts} (cycle ${cycle}, pos 2/3) — next in 3h`;\n    } else {\n      if (cycle === 1) {\n        status = 'NO_ANSWER';\n        nextFollowUpAt = addBusinessDays(nowDate, 2);\n        notes = `🟡 No answer (SIP ${sipCode}) — end of cycle 1 (3/3) — next cycle in 2 business days`;\n      } else if (cycle === 2) {\n        status = 'NO_ANSWER';\n        nextFollowUpAt = addBusinessDays(nowDate, 3);\n        notes = `🟡 No answer (SIP ${sipCode}) — end of cycle 2 (3/3) — next cycle in 3 business days`;\n      } else {\n        status = 'CLOSED';\n        nextFollowUpAt = null;\n        notes = `⛔ No answer (SIP ${sipCode}) — end of cycle 3 (9 total attempts) — CLOSED`;\n      }\n    }\n  } else {\n    status = 'UNREACHABLE';\n    last_call_status = sipCode ? ('SIP_' + sipCode) : 'OTHER_ERROR';\n    notes = '🔴 Unreachable: ' + message.slice(0, 150);\n  }\n\n  console.log('📞 Asterisk —', lead.lead_id, '| attempt:', attempts, '| status:', status, '| next:', nextFollowUpAt);\n\n  return { json: {\n    lead_id: lead.lead_id,\n    country: lead.country,\n    elevenlabs_call_id: conversationId,\n    status,\n    last_call_status,\n    notes,\n    call_attempts: attempts,\n    last_call_time: now,\n    nextFollowUpAt\n  }};\n});"},"id":"455a0688-154b-4c7a-b77d-8d6e7a8ec60b","name":"🔍 Classify Dial Result (Asterisk)1","type":"n8n-nodes-base.code","typeVersion":2,"position":[-18432,-2304],"disabled":true},{"parameters":{"method":"PATCH","url":"=https://lead-studio-9gnl.onrender.com/api/leads/{{ $json.lead_id }}","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Authorization","value":"=Bearer {{ $('🔐 Login LeadStudio').first().json.accessToken }}"}]},"sendBody":true,"specifyBody":"json","jsonBody":"={\n  \"status\": \"{{ $json.status }}\"{{ $json.call_attempts !== null ? ', \"attempts\": ' + $json.call_attempts : '' }}{{ $json.nextFollowUpAt ? ', \"nextFollowUpAt\": \"' + $json.nextFollowUpAt + '\"' : '' }}\n}\n","options":{"response":{"response":{"neverError":true,"responseFormat":"json"}},"timeout":15000}},"id":"98b6c467-340f-44a3-8b1c-d5f8ce797870","name":"🏁 PATCH Status Final (Asterisk)1","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[-18160,-2480],"disabled":true},{"parameters":{"method":"POST","url":"=https://lead-studio-9gnl.onrender.com/api/leads/{{ $('🔍 Classify Dial Result (Asterisk)1').item.json.lead_id }}/followups","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Authorization","value":"=Bearer {{ $('🔐 Login LeadStudio').first().json.accessToken }}"}]},"sendBody":true,"specifyBody":"json","jsonBody":"={\n  \"type\": \"CALL\",\n  \"outcome\": \"{{ $json.status === 'CONTACTED' ? 'CONNECTED' : $json.status === 'NO_ANSWER' ? 'NO_ANSWER' : 'WRONG_NUMBER' }}\",\n  \"callStatus\": \"{{ $json.last_call_status === 'ANSWERED' ? 'ANSWERED' : $json.last_call_status && $json.last_call_status.includes('NO_ANSWER') ? 'NO_ANSWER' : 'FAILED' }}\",\n  \"durationSeconds\": 0,\n  \"notes\": \"{{ $json.notes }}\"\n}","options":{"response":{"response":{"neverError":true,"responseFormat":"json"}},"timeout":15000}},"id":"7849efe8-1042-40ef-9a43-5f3c67b832ae","name":"💾 POST Followup (Asterisk)1","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[-17952,-2304],"disabled":true},{"parameters":{"url":"=https://lead-studio-9gnl.onrender.com/api/leads/queue","sendQuery":true,"queryParameters":{"parameters":[{"name":"limit","value":"50"},{"name":"dialCode","value":"91"}]},"sendHeaders":true,"headerParameters":{"parameters":[{"name":"Authorization","value":"=Bearer {{ $json.accessToken }}"}]},"options":{"response":{"response":{"neverError":true,"responseFormat":"json"}},"timeout":15000}},"id":"31e2b74b-e44c-4e75-af1e-475874ab75e7","name":"📞 GET Queue India (Stringee)1","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[-19808,-1616],"disabled":true},{"parameters":{"jsCode":"// Normaliza + selecciona batch de leads India (API LeadStudio) para Stringee.\n// CRITERIO DE LISTO PARA LLAMAR: status === 'NOT_CONTACTED'. BATCH_SIZE=1 (capacidad real del canal).\nfunction toE164(raw) {\n  if (raw === undefined || raw === null) return '';\n  let p = String(raw).replace(/[^0-9+]/g, '');\n  if (!p) return '';\n  if (p.startsWith('+')) return p;\n  if (p.length >= 8 && p.length <= 15) return '+' + p;\n  return '';\n}\n\nconst BATCH_SIZE = 1;\nconst leads = ($input.first().json.leads) || [];\nconst attempts = [];\nconst skipped = [];\n\nfor (const l of leads) {\n  const status = String(l.status || '').trim().toUpperCase();\n  if (!l.id) { skipped.push({ lead_id: 'EMPTY', reason: 'missing id' }); continue; }\n  if (l.doNotCall) { skipped.push({ lead_id: l.id, reason: 'doNotCall' }); continue; }\n  if (status !== 'NOT_CONTACTED') { skipped.push({ lead_id: l.id, reason: `status=${status} (no es NOT_CONTACTED)` }); continue; }\n\n  const phone = toE164(l.phone);\n  if (!phone) { skipped.push({ lead_id: l.id, reason: `bad phone: '${l.phone}'` }); continue; }\n\n  attempts.push({ json: {\n    lead_id: String(l.id), full_name: String(l.name || '').trim() || 'User',\n    phone, country: l.country || 'India',\n    language: String(l.language || 'hi').trim().toLowerCase(),\n    call_attempts: Number(l.attempts || 0)\n  }});\n}\n\nconsole.log('⚙️ Stringee — elegibles (NOT_CONTACTED):', attempts.length, '| skipped:', skipped.length, JSON.stringify(skipped).slice(0,500));\nreturn attempts.slice(0, BATCH_SIZE);\n"},"id":"9ebbf4ea-11f9-4f8d-bb1e-1d5a52d49849","name":"⚙️ Normalize & Select (Stringee)1","type":"n8n-nodes-base.code","typeVersion":2,"position":[-19568,-1616],"disabled":true},{"parameters":{"method":"POST","url":"http://172.18.0.1:8091/call","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Content-Type","value":"application/json"}]},"sendBody":true,"specifyBody":"json","jsonBody":"={\n  \"lead_id\": \"{{ $('⚙️ Normalize & Select (Stringee)1').item.json.lead_id }}\",\n  \"phone\": \"{{ $('⚙️ Normalize & Select (Stringee)1').item.json.phone.replace(/^\\+/, '') }}\",\n  \"full_name\": \"{{ $('⚙️ Normalize & Select (Stringee)1').item.json.full_name }}\",\n  \"country\": \"{{ $('⚙️ Normalize & Select (Stringee)1').item.json.country }}\",\n  \"language\": \"{{ $('⚙️ Normalize & Select (Stringee)1').item.json.language || 'hi' }}\",\n  \"is_followup\": \"false\",\n  \"call_attempts\": {{ Number($('⚙️ Normalize & Select (Stringee)1').item.json.call_attempts || 0) + 1 }},\n  \"from_number\": \"917971730907\",\n  \"agent_id\": \"agent_5701kramx550e3qs2tm11661b48p\"\n}","options":{"batching":{"batch":{"batchSize":5,"batchInterval":0}},"response":{"response":{"fullResponse":true,"neverError":true,"responseFormat":"json"}},"timeout":45000}},"id":"53a82856-5e57-4dd1-8a0a-a1fbafcefa67","name":"📞 POST → Stringee Worker1","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[-19088,-1616],"disabled":true},{"parameters":{"jsCode":"// Stringee: el worker solo confirma que la llamada se DISPARÓ (job_id), no si\n// contestó o no — eso llega después por webhook a otro workflow. Por eso acá\n// solo se puede marcar ACTIVE (se disparó bien) o UNREACHABLE (falló el disparo).\n// El ciclo de reintentos NO_ANSWER (2h/3h/2d/3d) para Stringee no se puede calcular\n// en este punto — falta esa pieza en el workflow que reciba el resultado final.\nconst items = $input.all();\nconst leads = $('⚙️ Normalize & Select (Stringee)1').all();\nconst now = new Date().toISOString();\n\nreturn items.map((item, i) => {\n  const resp = item.json || {};\n  const lead = (leads[i] || leads[0]).json;\n  const statusCode = Number(resp.statusCode ?? resp.status ?? (resp.headers ? 200 : 0));\n  const body = resp.body ?? resp;\n  const jobId = String(body.job_id || body.jobId || '');\n\n  let status, last_call_status, notes;\n  if (statusCode >= 200 && statusCode < 300 && body.ok === true && jobId) {\n    status = 'ATTEMPTING';\n    last_call_status = 'DISPATCHED';\n    notes = '🟢 Stringee worker job: ' + jobId;\n  } else if (statusCode >= 400) {\n    status = 'UNREACHABLE';\n    last_call_status = 'HTTP_' + statusCode;\n    notes = '🔴 Stringee Worker ' + statusCode + ': ' + JSON.stringify(body).slice(0, 200);\n  } else {\n    status = 'UNREACHABLE';\n    last_call_status = 'NO_JOB_ID';\n    notes = '🟡 Unexpected Stringee worker response: ' + JSON.stringify(body).slice(0, 200);\n  }\n\n  console.log('📞 Stringee —', lead.lead_id, '| HTTP', statusCode, '| status:', status, '| job_id:', jobId);\n\n  return { json: {\n    lead_id: lead.lead_id,\n    status,\n    last_call_status,\n    notes,\n    call_attempts: Number(lead.call_attempts || 0) + 1,\n    last_call_time: now,\n    nextFollowUpAt: null\n  }};\n});\n"},"id":"dde950b9-be26-4c0b-9411-60357b7dde80","name":"🔍 Classify Result (Stringee)1","type":"n8n-nodes-base.code","typeVersion":2,"position":[-18848,-1616],"disabled":true},{"parameters":{"method":"PATCH","url":"=https://lead-studio-9gnl.onrender.com/api/leads/{{ $json.lead_id }}","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Authorization","value":"=Bearer {{ $('🔐 Login LeadStudio').first().json.accessToken }}"}]},"sendBody":true,"specifyBody":"json","jsonBody":"={\n  \"status\": \"{{ $json.status }}\"{{ $json.call_attempts !== null ? ', \"attempts\": ' + $json.call_attempts : '' }}{{ $json.nextFollowUpAt ? ', \"nextFollowUpAt\": \"' + $json.nextFollowUpAt + '\"' : '' }}\n}","options":{"response":{"response":{"neverError":true,"responseFormat":"json"}},"timeout":15000}},"id":"64ea95fb-d422-4e3a-b7ff-e2e844e48873","name":"🏁 PATCH Status Final (Stringee)1","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[-18608,-1616],"disabled":true},{"parameters":{"method":"POST","url":"=https://lead-studio-9gnl.onrender.com/api/leads/{{ $('🔍 Classify Result (Stringee)1').item.json.lead_id }}/followups","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Authorization","value":"=Bearer {{ $('🔐 Login LeadStudio').first().json.accessToken }}"}]},"sendBody":true,"specifyBody":"json","jsonBody":"={\n  \"type\": \"CALL\",\n  \"outcome\": \"{{ $input.first().json.status === 'CONTACTED' ? 'CONNECTED' : $input.first().json.status === 'UNREACHABLE' ? 'FAILED' : 'NO_ANSWER' }}\",\n  \"callStatus\": \"{{ $input.first().json.last_call_status === 'DISPATCHED' ? 'ANSWERED' : 'FAILED' }}\",\n  \"durationSeconds\": 0,\n  \"notes\": \"{{ $input.first().json.notes }}\"\n}","options":{"response":{"response":{"neverError":true,"responseFormat":"json"}},"timeout":15000}},"id":"87c44d8d-01d7-430f-a9ce-4ef87ceb2fc8","name":"💾 POST Followup (Stringee)1","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[-18368,-1616],"disabled":true},{"parameters":{"method":"POST","url":"=https://lead-studio-9gnl.onrender.com/api/auth/login","sendBody":true,"specifyBody":"json","jsonBody":"={\n  \"email\": \"ai@leadstudio.com\",\n  \"password\": \"Admin@123\"\n}","options":{"response":{"response":{"neverError":true,"responseFormat":"json"}},"timeout":15000}},"id":"0fd98474-1411-461f-8947-e63d588eedf2","name":"🔐 Login LeadStudio","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[-22000,-1024],"disabled":true},{"parameters":{"rule":{"interval":[{"field":"minutes","minutesInterval":1}]}},"id":"5291ce44-4973-495b-8264-93f47cfcb497","name":"⏰ Trigger Dialer (cada 1 min)","type":"n8n-nodes-base.scheduleTrigger","typeVersion":1.3,"position":[-22960,1392],"disabled":true},{"parameters":{"httpMethod":"POST","path":"dial-now-unificado-v2","options":{}},"id":"37e2588d-09f2-4a70-b544-b4561a32c943","name":"🪝 Manual Trigger (test manual)","webhookId":"dial-now-unificado-v2","type":"n8n-nodes-base.webhook","typeVersion":2,"position":[-22960,1600],"disabled":true},{"parameters":{"operation":"executeQuery","query":"SELECT provider, enabled FROM wf2_provider_config;","options":{}},"id":"75b59dbb-571a-4602-8caa-a48a822481cd","name":"🗄️ Leer Providers Activos (MySQL)","type":"n8n-nodes-base.mySql","typeVersion":2.4,"position":[-22720,1392],"alwaysOutputData":true,"credentials":{"mySql":{"id":"4NiWyzzJ4JbMkIjT","name":"MySQL account"}},"disabled":true,"onError":"continueRegularOutput"},{"parameters":{"jsCode":"// Lee wf2_provider_config. Fail-open: si falta la tabla/fila, el proveedor queda HABILITADO.\nconst rows = $input.all().map(i => i.json).filter(r => r && r.provider);\nfunction isEnabled(name) {\n  const row = rows.find(r => String(r.provider).toLowerCase() === name);\n  if (!row) return true;\n  return Number(row.enabled) === 1;\n}\nconst asterisk_enabled = isEnabled('asterisk');\nconst stringee_enabled = isEnabled('stringee');\nconsole.log('🔀 Providers —', 'Asterisk:', asterisk_enabled, '| Stringee:', stringee_enabled);\nreturn [{ json: { asterisk_enabled, stringee_enabled } }];\n"},"id":"ff5479d2-15fb-4747-87c6-1b2d44b3b590","name":"⚙️ Calcular Providers Activos","type":"n8n-nodes-base.code","typeVersion":2,"position":[-22480,1392],"disabled":true},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"loose","version":2},"conditions":[{"id":"2e580fa3-94a3-4db3-9217-083c797b7c05","leftValue":"={{ $json.accessToken || '' }}","rightValue":"","operator":{"type":"string","operation":"notEmpty","singleValue":true}}],"combinator":"and"},"options":{}},"id":"d0af2768-2992-4aa7-b0c9-1846439a6e67","name":"✅ Token OK?","type":"n8n-nodes-base.if","typeVersion":2.2,"position":[-22000,1392],"disabled":true},{"parameters":{"jsCode":"const resp = $('🔐 Login LeadStudio1').first().json;\nconsole.error('❌ WF2: Login a LeadStudio falló', JSON.stringify(resp).slice(0, 500));\nreturn [{ json: { error: true, message: 'LeadStudio auth failed', response: resp } }];\n"},"id":"5fd35527-fce0-4d1c-93cd-5c98dcf1a818","name":"❌ Log Auth Error","type":"n8n-nodes-base.code","typeVersion":2,"position":[-21760,1552],"disabled":true},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"loose","version":2},"conditions":[{"id":"4c89d07a-0221-4e58-8616-693fa1ff6f0d","leftValue":"={{ $('⚙️ Calcular Providers Activos').first().json.asterisk_enabled }}","rightValue":true,"operator":{"type":"boolean","operation":"true","singleValue":true}}],"combinator":"and"},"options":{}},"id":"622fa0a5-8de9-4b69-901f-852411ba7b00","name":"🔀 Asterisk Habilitado?","type":"n8n-nodes-base.if","typeVersion":2.2,"position":[-21760,1152],"disabled":true},{"parameters":{"jsCode":"console.log('⏸️ Asterisk DESACTIVADO por wf2_provider_config — ciclo omitido');\nreturn [{ json: { skipped: true, provider: 'asterisk', at: new Date().toISOString() } }];\n"},"id":"45f7f3a0-6e5f-461e-96b1-253341039244","name":"⏸️ Asterisk Desactivado (log)","type":"n8n-nodes-base.code","typeVersion":2,"position":[-21520,1312],"disabled":true},{"parameters":{"jsCode":"const BASE = 'https://lead-studio-9gnl.onrender.com/api';\nconst TOKEN = $('🔐 Login LeadStudio1').first().json.accessToken;\nconst self = this;\n\nasync function api(method, path, opts = {}) {\n  try {\n    const r = await self.helpers.httpRequest({\n      method,\n      url: BASE + path,\n      qs: opts.qs,\n      body: opts.body,\n      json: true,\n      headers: {\n        Authorization: 'Bearer ' + TOKEN,\n        'Content-Type': 'application/json'\n      },\n      returnFullResponse: true,\n      ignoreHttpStatusErrors: true,\n      timeout: 20000\n    });\n\n    return {\n      ok: r.statusCode >= 200 && r.statusCode < 300,\n      status: r.statusCode,\n      body: r.body || {}\n    };\n  } catch (e) {\n    return {\n      ok: false,\n      status: 0,\n      body: { error: String(e.message || e) }\n    };\n  }\n}\n\n// ============================================================================\n// 📥 FETCH + LOCK (ASTERISK)\n//\n// Regla:\n// 3 ciclos x 3 intentos = máximo 9.\n//\n// attempts 0-8  -> puede despacharse.\n// attempts >= 9 -> NO se despacha.\n//                  status CLOSED.\n//                  stage LOST.\n//\n// El bloqueo ocurre ANTES de ElevenLabs.\n// ============================================================================\n\nconst MAX_ATTEMPTS = 9;\n\nconst COUNTRIES = [\n  {\n    key: 'india',\n    dialCode: '91',\n    prefix: '+91',\n    batchSize: 10,\n    minDigits: 10,\n    maxDigits: 10,\n    language: 'hi',\n    agent_id: 'agent_5701kramx550e3qs2tm11661b48p',\n    agent_phone_number_id: 'phnum_7801kyktmabxembteqce884tanb6'\n  },\n  {\n    key: 'nepal',\n    dialCode: '977',\n    prefix: '+977',\n    batchSize: 6,\n    minDigits: 8,\n    maxDigits: 10,\n    language: 'hi',\n    agent_id: 'agent_7601m209ntj3fyrbg0dcq6w507yq',\n    agent_phone_number_id: 'phnum_7801kyktmabxembteqce884tanb6'\n  }\n];\n\nconst FETCH_MULT = 3;\n\nfunction normalizePhone(raw, prefix) {\n  let p = String(raw || '').replace(/[^0-9+]/g, '');\n\n  if (!p) return '';\n\n  if (p.startsWith('+')) return p;\n\n  const digits = prefix.replace('+', '');\n\n  if (\n    p.startsWith(digits) &&\n    p.length > digits.length + 6\n  ) {\n    return '+' + p;\n  }\n\n  return prefix + p;\n}\n\nfunction safeAttempts(value) {\n  const n = Number(value);\n\n  if (!Number.isFinite(n) || n < 0) {\n    return 0;\n  }\n\n  return Math.trunc(n);\n}\n\n// Cierra un lead agotado.\n// Primero CLOSED para impedir nuevas llamadas.\n// Después intenta mover el stage a LOST.\nasync function closeExhaustedLead(leadId, attempts, country) {\n  const close = await api(\n    'PATCH',\n    `/leads/${leadId}`,\n    {\n      body: {\n        status: 'CLOSED'\n      }\n    }\n  );\n\n  if (!close.ok) {\n    console.error(\n      `🚨 Asterisk ${country}: no se pudo cerrar ${leadId} ` +\n      `con ${attempts} intentos. HTTP ${close.status}. ` +\n      `Por seguridad NO se despacha.`\n    );\n\n    return {\n      closed: false,\n      lost: false\n    };\n  }\n\n  const lost = await api(\n    'PATCH',\n    `/leads/${leadId}`,\n    {\n      body: {\n        stage: 'LOST'\n      }\n    }\n  );\n\n  if (!lost.ok) {\n    console.error(\n      `⚠️ Asterisk ${country}: ${leadId} quedó CLOSED, ` +\n      `pero stage LOST falló HTTP ${lost.status}.`\n    );\n  }\n\n  console.log(\n    `⛔ Asterisk ${country}: ${leadId} reached ` +\n    `${attempts}/${MAX_ATTEMPTS} attempts → no dispatch`\n  );\n\n  return {\n    closed: true,\n    lost: lost.ok\n  };\n}\n\nconst out = [];\n\nfor (const c of COUNTRIES) {\n  const limit = Math.min(\n    200,\n    c.batchSize * FETCH_MULT\n  );\n\n  let offset = 0;\n\n  if (c.fromEnd) {\n    const t = await api(\n      'GET',\n      '/leads',\n      {\n        qs: {\n          status: 'NOT_CONTACTED',\n          dialCode: c.dialCode,\n          limit: 1,\n          offset: 0\n        }\n      }\n    );\n\n    offset = t.ok\n      ? Math.max(\n          0,\n          Number(t.body.total || 0) - limit\n        )\n      : 0;\n  }\n\n  const r = await api(\n    'GET',\n    '/leads',\n    {\n      qs: {\n        status: 'NOT_CONTACTED',\n        dialCode: c.dialCode,\n        limit,\n        offset\n      }\n    }\n  );\n\n  if (!r.ok) {\n    console.error(\n      `❌ Asterisk ${c.key}: GET /leads falló HTTP ${r.status}`,\n      JSON.stringify(r.body).slice(0, 300)\n    );\n\n    continue;\n  }\n\n  const leads = r.body.leads || [];\n  const totalDisponibles = Number(r.body.total || 0);\n\n  let taken = 0;\n  let invalid = 0;\n  let lockFail = 0;\n  let exhausted = 0;\n\n  for (const l of leads) {\n    if (taken >= c.batchSize) break;\n\n    if (!l || !l.id) continue;\n\n    if (\n      String(l.status || '').toUpperCase() !== 'NOT_CONTACTED'\n    ) {\n      continue;\n    }\n\n    const currentAttempts = safeAttempts(l.attempts);\n\n    // ==========================================================\n    // HARD LIMIT\n    // Si ya tiene 9 intentos o más, nunca llega a ElevenLabs.\n    // ==========================================================\n    if (currentAttempts >= MAX_ATTEMPTS) {\n      await closeExhaustedLead(\n        l.id,\n        currentAttempts,\n        c.key\n      );\n\n      exhausted++;\n      continue;\n    }\n\n    if (l.doNotCall) {\n      await api(\n        'PATCH',\n        `/leads/${l.id}`,\n        {\n          body: {\n            status: 'CLOSED'\n          }\n        }\n      );\n\n      invalid++;\n      continue;\n    }\n\n    const phone = normalizePhone(\n      l.phone,\n      c.prefix\n    );\n\n    const national = phone.slice(\n      c.prefix.length\n    );\n\n    const validPhone =\n      /^\\+[1-9]\\d{7,14}$/.test(phone) &&\n      phone.startsWith(c.prefix) &&\n      national.length >= c.minDigits &&\n      national.length <= c.maxDigits;\n\n    if (!validPhone) {\n      await api(\n        'PATCH',\n        `/leads/${l.id}`,\n        {\n          body: {\n            status: 'UNREACHABLE'\n          }\n        }\n      );\n\n      console.log(\n        `🚫 ${c.key}: teléfono inválido '${l.phone}' ` +\n        `→ UNREACHABLE (${l.id})`\n      );\n\n      invalid++;\n      continue;\n    }\n\n    // Lock antes de llamar.\n    const lock = await api(\n      'PATCH',\n      `/leads/${l.id}`,\n      {\n        body: {\n          status: 'ATTEMPTING'\n        }\n      }\n    );\n\n    if (!lock.ok) {\n      lockFail++;\n\n      console.error(\n        `🔒❌ ${c.key}: no se pudo bloquear ${l.id} ` +\n        `HTTP ${lock.status}`\n      );\n\n      continue;\n    }\n\n    out.push({\n      json: {\n        provider: 'asterisk',\n        lead_id: l.id,\n        full_name:\n          String(l.name || '').trim() || 'User',\n        phone,\n        country: c.key,\n        language:\n          String(l.language || c.language)\n            .trim()\n            .toLowerCase(),\n\n        call_attempts: currentAttempts,\n\n        _agent_id: c.agent_id,\n        _agent_phone_number_id:\n          c.agent_phone_number_id,\n\n        _from_number: c.lines\n          ? c.lines[taken % c.lines.length]\n          : (c.from_number || '')\n      }\n    });\n\n    taken++;\n  }\n\n  const msg =\n    `📥 Asterisk ${c.key}: ` +\n    `${totalDisponibles} NOT_CONTACTED | ` +\n    `${leads.length} leídos | ` +\n    `${taken} bloqueados | ` +\n    `${exhausted} agotaron ${MAX_ATTEMPTS} intentos | ` +\n    `${invalid} inválidos | ` +\n    `${lockFail} lock fallidos`;\n\n  if (\n    taken === 0 &&\n    totalDisponibles > 0\n  ) {\n    console.error(\n      '🚨 Hay leads disponibles pero 0 llegaron al batch — ' +\n      msg\n    );\n  } else {\n    console.log(msg);\n  }\n}\n\nreturn out;"},"id":"8a5131c3-30f8-445d-8247-2bdb4145c235","name":"📥 Fetch + Lock (Asterisk)","type":"n8n-nodes-base.code","typeVersion":2,"position":[-21520,1072],"disabled":true},{"parameters":{"method":"POST","url":"https://api.elevenlabs.io/v1/convai/sip-trunk/outbound-call","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Content-Type","value":"application/json"},{"name":"xi-api-key","value":"sk_79048a9776812db4416e5c690d0c047132d565fee7d43acd"}]},"sendBody":true,"specifyBody":"json","jsonBody":"={\n  \"agent_id\": \"{{ $json._agent_id }}\",\n  \"agent_phone_number_id\": \"{{ $json._agent_phone_number_id }}\",\n  \"to_number\": \"{{ $json.phone }}\",\n  \"conversation_initiation_client_data\": {\n    \"conversation_config_override\": {\n      \"agent\": { \"language\": \"{{ $json.language }}\" }\n    },\n    \"dynamic_variables\": {\n      \"lead_id\": \"{{ $json.lead_id }}\",\n      \"full_name\": {{ JSON.stringify($json.full_name) }},\n      \"phone\": \"{{ $json.phone }}\",\n      \"country\": \"{{ $json.country }}\",\n      \"language\": \"{{ $json.language }}\",\n      \"is_followup\": \"{{ $json.call_attempts > 0 ? 'true' : 'false' }}\",\n      \"call_attempts\": \"{{ Number($json.call_attempts || 0) + 1 }}\"\n    }\n  }\n}","options":{"batching":{"batch":{"batchSize":5,"batchInterval":0}},"response":{"response":{"fullResponse":true,"neverError":true,"responseFormat":"json"}},"timeout":60000}},"id":"1117f3f1-8e96-44c2-a3ec-c63ea1544fef","name":"📞 POST → ElevenLabs Dial (Asterisk)","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[-21280,1072],"credentials":{"httpHeaderAuth":{"id":"ui7o7nfbbbmdISf2","name":"Header Auth account"}},"disabled":true,"onError":"continueRegularOutput"},{"parameters":{"jsCode":"// ============================================================================\n// 🔍 CLASSIFY DIAL RESULT (ASTERISK)\n//\n// CRM visible text: ENGLISH ONLY.\n// Comentarios/logs internos: español.\n//\n// Ciclo 1: attempts 1-3\n// Ciclo 2: attempts 4-6\n// Ciclo 3: attempts 7-9\n//\n// Attempt 9 + NO_ANSWER -> CLOSED + LOST.\n// ============================================================================\n\nconst items = $input.all();\nconst src = $('📥 Fetch + Lock (Asterisk)').all();\n\nconst nowDate = new Date();\n\nconst NO_ANSWER_CODES = [\n  '603',\n  '408',\n  '486'\n];\n\nconst MAX_ATTEMPTS = 9;\nconst ATTEMPTS_PER_CYCLE = 3;\nconst MAX_CYCLES = 3;\n\nfunction addHours(d, h) {\n  return new Date(\n    d.getTime() + h * 3600000\n  ).toISOString();\n}\n\nfunction addBusinessDays(d, days) {\n  const r = new Date(d.getTime());\n  let added = 0;\n\n  while (added < days) {\n    r.setDate(r.getDate() + 1);\n\n    const weekday = r.getDay();\n\n    if (\n      weekday !== 0 &&\n      weekday !== 6\n    ) {\n      added++;\n    }\n  }\n\n  return r.toISOString();\n}\n\nfunction safeAttempts(value) {\n  const n = Number(value);\n\n  if (!Number.isFinite(n) || n < 0) {\n    return 0;\n  }\n\n  return Math.trunc(n);\n}\n\nfunction pickLead(item, i) {\n  let idx = i;\n\n  const p = item.pairedItem;\n\n  if (\n    p !== undefined &&\n    p !== null\n  ) {\n    const pi = Array.isArray(p)\n      ? p[0]\n      : p;\n\n    if (typeof pi === 'number') {\n      idx = pi;\n    } else if (\n      pi &&\n      typeof pi.item === 'number'\n    ) {\n      idx = pi.item;\n    }\n  }\n\n  return (\n    src[idx] ||\n    src[i] ||\n    src[0]\n  ).json;\n}\n\nfunction isProviderFail(httpStatus, message) {\n  if (\n    httpStatus === 0 ||\n    httpStatus === 401 ||\n    httpStatus === 402 ||\n    httpStatus === 403 ||\n    httpStatus === 429 ||\n    httpStatus >= 500\n  ) {\n    return true;\n  }\n\n  return /concurren|rate.?limit|quota|credit|insufficient|too many/i.test(\n    message\n  );\n}\n\nlet providerFails = 0;\n\nconst out = items.map((item, i) => {\n  const lead = pickLead(item, i);\n\n  const resp = item.json || {};\n\n  const httpStatus = Number(\n    resp.statusCode ?? 0\n  );\n\n  const body =\n    (\n      resp.body !== undefined\n        ? resp.body\n        : resp\n    ) || {};\n\n  const detail = body.detail;\n\n  let message =\n    body.message ||\n    (\n      detail &&\n      (\n        typeof detail === 'string'\n          ? detail\n          : (\n              detail.message ||\n              JSON.stringify(detail)\n            )\n      )\n    ) ||\n    body.error ||\n    resp.error ||\n    '';\n\n  if (typeof message !== 'string') {\n    message = JSON.stringify(message);\n  }\n\n  const conversationId =\n    body.conversation_id || '';\n\n  const success =\n    body.success === true;\n\n  const sipMatch =\n    message.match(/SIP\\s*(\\d{3})/i) ||\n    message.match(/\\b(\\d{3})\\b/);\n\n  const sipCode = sipMatch\n    ? sipMatch[1]\n    : null;\n\n  const isNoAnswer =\n    !!sipCode &&\n    NO_ANSWER_CODES.includes(sipCode);\n\n  const previousAttempts =\n    safeAttempts(lead.call_attempts);\n\n  const attempts =\n    previousAttempts + 1;\n\n  let r;\n\n  // ==========================================================\n  // ANSWERED\n  // Aunque sea attempt 9, si contestó NO va a LOST.\n  // ==========================================================\n  if (\n    success &&\n    conversationId\n  ) {\n    r = {\n      status: 'CONTACTED',\n      stage: null,\n      attempts,\n      nextFollowUpAt: null,\n      last_call_status: 'ANSWERED',\n      outcome: 'CONNECTED',\n      callStatus: 'ANSWERED',\n      notes:\n        'Call connected successfully: ' +\n        conversationId,\n      logFollowup: true\n    };\n  }\n\n  // ==========================================================\n  // NO ANSWER\n  // ==========================================================\n  else if (isNoAnswer) {\n    const pos =\n      ((attempts - 1) % ATTEMPTS_PER_CYCLE) + 1;\n\n    const cycle =\n      Math.ceil(\n        attempts / ATTEMPTS_PER_CYCLE\n      );\n\n    let status = 'NO_ANSWER';\n    let stage = null;\n    let next = null;\n    let notes = '';\n\n    // Intento 9 = fin definitivo.\n    if (attempts >= MAX_ATTEMPTS) {\n      status = 'CLOSED';\n      stage = 'LOST';\n      next = null;\n\n      notes =\n        `No answer (SIP ${sipCode}) — ` +\n        `end of cycle ${MAX_CYCLES} (3/3) — ` +\n        `maximum ${MAX_ATTEMPTS} call attempts reached.`;\n    }\n\n    else if (pos === 1) {\n      next = addHours(\n        nowDate,\n        2\n      );\n\n      notes =\n        `No answer (SIP ${sipCode}) — ` +\n        `attempt ${attempts} ` +\n        `(cycle ${cycle}, 1/3) — ` +\n        `next attempt in 2 hours.`;\n    }\n\n    else if (pos === 2) {\n      next = addHours(\n        nowDate,\n        3\n      );\n\n      notes =\n        `No answer (SIP ${sipCode}) — ` +\n        `attempt ${attempts} ` +\n        `(cycle ${cycle}, 2/3) — ` +\n        `next attempt in 3 hours.`;\n    }\n\n    else if (cycle === 1) {\n      next = addBusinessDays(\n        nowDate,\n        2\n      );\n\n      notes =\n        `No answer (SIP ${sipCode}) — ` +\n        `end of cycle 1 (3/3) — ` +\n        `next cycle in 2 business days.`;\n    }\n\n    else if (cycle === 2) {\n      next = addBusinessDays(\n        nowDate,\n        3\n      );\n\n      notes =\n        `No answer (SIP ${sipCode}) — ` +\n        `end of cycle 2 (3/3) — ` +\n        `next cycle in 3 business days.`;\n    }\n\n    else {\n      // Defensa extra. No debería alcanzarse.\n      status = 'CLOSED';\n      stage = 'LOST';\n      next = null;\n\n      notes =\n        `No answer (SIP ${sipCode}) — ` +\n        `maximum ${MAX_ATTEMPTS} call attempts reached.`;\n    }\n\n    r = {\n      status,\n      stage,\n      attempts,\n      nextFollowUpAt: next,\n      last_call_status:\n        'NO_ANSWER_SIP_' + sipCode,\n      outcome: 'NO_ANSWER',\n      callStatus: 'NO_ANSWER',\n      notes,\n      logFollowup: true\n    };\n  }\n\n  // ==========================================================\n  // ERROR DEL PROVEEDOR\n  // No consume intento.\n  // ==========================================================\n  else if (\n    isProviderFail(\n      httpStatus,\n      message\n    )\n  ) {\n    providerFails++;\n\n    r = {\n      status: 'NOT_CONTACTED',\n      stage: null,\n      attempts: null,\n      nextFollowUpAt: null,\n      last_call_status:\n        'PROVIDER_ERROR_' + httpStatus,\n      outcome: null,\n      callStatus: null,\n      notes:\n        'Provider error. The lead was returned to the call queue.',\n      logFollowup: false\n    };\n  }\n\n  // ==========================================================\n  // OTRO ERROR\n  // ==========================================================\n  else {\n    const exhausted =\n      attempts >= MAX_ATTEMPTS;\n\n    r = {\n      status: exhausted\n        ? 'CLOSED'\n        : 'UNREACHABLE',\n\n      stage: exhausted\n        ? 'LOST'\n        : null,\n\n      attempts,\n      nextFollowUpAt: null,\n\n      last_call_status:\n        sipCode\n          ? 'SIP_' + sipCode\n          : 'OTHER_ERROR',\n\n      outcome: 'WRONG_NUMBER',\n      callStatus: 'FAILED',\n\n      notes: exhausted\n        ? (\n            `Call failed — attempt ${attempts}/${MAX_ATTEMPTS} — ` +\n            `maximum call attempts reached.`\n          )\n        : (\n            `Call failed or unreachable: ` +\n            message.slice(0, 150)\n          ),\n\n      logFollowup: true\n    };\n  }\n\n  console.log(\n    '📞 Asterisk —',\n    lead.lead_id,\n    '| HTTP',\n    httpStatus,\n    '| attempt',\n    attempts,\n    '| →',\n    r.status,\n    r.stage\n      ? '| stage ' + r.stage\n      : '',\n    '| next:',\n    r.nextFollowUpAt\n  );\n\n  return {\n    json: {\n      provider: 'asterisk',\n      lead_id: lead.lead_id,\n      country: lead.country,\n      elevenlabs_call_id:\n        conversationId,\n      last_call_time:\n        nowDate.toISOString(),\n      ...r\n    }\n  };\n});\n\nif (providerFails > 0) {\n  console.error(\n    `🚨 ElevenLabs: ${providerFails}/${items.length} ` +\n    `llamadas fallaron por problema del proveedor.`\n  );\n}\n\nreturn out;"},"id":"7874a906-3d6b-4084-ac0a-e3915494e032","name":"🔍 Classify Dial Result (Asterisk)","type":"n8n-nodes-base.code","typeVersion":2,"position":[-21040,1072],"disabled":true},{"parameters":{"jsCode":"const BASE = 'https://lead-studio-9gnl.onrender.com/api';\nconst TOKEN = $('🔐 Login LeadStudio1').first().json.accessToken;\nconst self = this;\n\nasync function api(method, path, opts = {}) {\n  try {\n    const r = await self.helpers.httpRequest({\n      method,\n      url: BASE + path,\n      qs: opts.qs,\n      body: opts.body,\n      json: true,\n      headers: {\n        Authorization: 'Bearer ' + TOKEN,\n        'Content-Type': 'application/json'\n      },\n      returnFullResponse: true,\n      ignoreHttpStatusErrors: true,\n      timeout: 20000\n    });\n\n    return {\n      ok:\n        r.statusCode >= 200 &&\n        r.statusCode < 300,\n      status: r.statusCode,\n      body: r.body || {}\n    };\n  } catch (e) {\n    return {\n      ok: false,\n      status: 0,\n      body: {\n        error: String(\n          e.message || e\n        )\n      }\n    };\n  }\n}\n\n// ============================================================================\n// 🏁 GUARDAR RESULTADO (ASTERISK)\n//\n// 1. POST followup.\n//    LeadStudio incrementa attempts.\n//\n// 2. PATCH status.\n//\n// 3. Si Classify pidió LOST,\n//    PATCH stage por separado.\n//\n// Se separa status de stage para no poner en riesgo\n// el cierre del lead si el stage fuera rechazado.\n// ============================================================================\n\nconst out = [];\nlet fails = 0;\nlet deferred = 0;\n\n// Este nodo va DESPUÉS del registro diferido (MySQL): $input trae las claves confirmadas;\n// las llamadas clasificadas vienen del nodo Classify.\nconst confirmedKeys = new Set(\n  $input.all().map(i => (i.json || {}).event_key).filter(Boolean).map(String)\n);\n\nfor (const item of $('🔍 Classify Dial Result (Asterisk)').all()) {\n  const j = item.json || {};\n\n  if (!j.lead_id) {\n    console.error(\n      '❌ Asterisk: item sin lead_id'\n    );\n    continue;\n  }\n\n  // ------------------------------------------------------------\n  // DIFERIDA (llamada contestada)\n  // LeadStudio fija durationSeconds en el POST y no lo deja editar\n  // después. Esta llamada acaba de ser contestada: todavía no existe\n  // el billsec. WF9 crea la ÚNICA Activity al terminar la llamada\n  // (durationSeconds = CDR.billsec) y aplica el ciclo de vida.\n  // Aquí NO se hace POST ni PATCH: el lead sigue ATTEMPTING y el\n  // Mantenimiento lo retiene mientras el registro esté sin resolver.\n  // Sólo si el registro durable quedó CONFIRMADO; si no, se conserva\n  // el comportamiento anterior (Activity inmediata): nunca se pierde\n  // una llamada.\n  // ------------------------------------------------------------\n  if (\n    String(j.outcome || '').toUpperCase() === 'CONNECTED' &&\n    String(j.callStatus || '').toUpperCase() === 'ANSWERED' &&\n    j.elevenlabs_call_id &&\n    confirmedKeys.has('elevenlabs:' + j.elevenlabs_call_id)\n  ) {\n    deferred++;\n    console.log(\n      `⏳ Asterisk ${j.lead_id}: contestada → la Activity la crea WF9 ` +\n      `al terminar (${j.elevenlabs_call_id})`\n    );\n    out.push({\n      json: {\n        ...j,\n        deferred_to_wf9: true,\n        patch_ok: null,\n        patch_http: null,\n        stage_requested: j.stage || null,\n        stage_ok: null,\n        stage_http: null,\n        followup_ok: null,\n        followup_id: null\n      }\n    });\n    continue;\n  }\n\n  // ------------------------------------------------------------\n  // FOLLOWUP\n  // ------------------------------------------------------------\n  let fu = null;\n\n  if (j.logFollowup) {\n    const fuBody = {\n      type: 'CALL',\n      outcome: j.outcome,\n      callStatus: j.callStatus,\n      durationSeconds: 0,\n      notes: j.notes\n    };\n\n    if (j.nextFollowUpAt) {\n      fuBody.nextActionAt =\n        j.nextFollowUpAt;\n    }\n\n    fu = await api(\n      'POST',\n      `/leads/${j.lead_id}/followups`,\n      {\n        body: fuBody\n      }\n    );\n\n    if (!fu.ok) {\n      console.error(\n        `⚠️ Followup falló ${j.lead_id} ` +\n        `HTTP ${fu.status}`,\n        JSON.stringify(\n          fu.body\n        ).slice(0, 200)\n      );\n    }\n  }\n\n  // ------------------------------------------------------------\n  // STATUS\n  // ------------------------------------------------------------\n  let r = await api(\n    'PATCH',\n    `/leads/${j.lead_id}`,\n    {\n      body: {\n        status: j.status\n      }\n    }\n  );\n\n  if (!r.ok) {\n    r = await api(\n      'PATCH',\n      `/leads/${j.lead_id}`,\n      {\n        body: {\n          status: j.status\n        }\n      }\n    );\n  }\n\n  if (!r.ok) {\n    fails++;\n\n    console.error(\n      `❌ PATCH status falló 2 veces ${j.lead_id} ` +\n      `HTTP ${r.status}`,\n      JSON.stringify(\n        r.body\n      ).slice(0, 200)\n    );\n  }\n\n  // ------------------------------------------------------------\n  // STAGE LOST\n  // Solo cuando Classify lo solicita.\n  // ------------------------------------------------------------\n  let stageResult = null;\n\n  if (\n    r.ok &&\n    j.stage\n  ) {\n    stageResult = await api(\n      'PATCH',\n      `/leads/${j.lead_id}`,\n      {\n        body: {\n          stage: j.stage\n        }\n      }\n    );\n\n    if (!stageResult.ok) {\n      // El status CLOSED ya quedó aplicado.\n      // Por eso no existe riesgo de otra llamada.\n      console.error(\n        `⚠️ Stage ${j.stage} falló para ${j.lead_id} ` +\n        `HTTP ${stageResult.status}. ` +\n        `El status ${j.status} sí quedó aplicado.`\n      );\n    }\n  }\n\n  const followupId =\n    fu &&\n    fu.ok &&\n    fu.body &&\n    fu.body.followUp\n      ? fu.body.followUp.id\n      : null;\n\n  out.push({\n    json: {\n      ...j,\n\n      patch_ok: r.ok,\n      patch_http: r.status,\n\n      stage_requested:\n        j.stage || null,\n\n      stage_ok:\n        stageResult\n          ? stageResult.ok\n          : null,\n\n      stage_http:\n        stageResult\n          ? stageResult.status\n          : null,\n\n      followup_ok:\n        fu\n          ? fu.ok\n          : null,\n\n      followup_id:\n        followupId\n    }\n  });\n}\n\nconsole.log(\n  `🏁 Asterisk: ${out.length} guardados | ` +\n  `${deferred} diferidos a WF9 | ` +\n  `${fails} PATCH fallidos`\n);\n\nreturn out;"},"id":"fae746f0-7b71-4a8f-8ad9-40af3b952b09","name":"🏁 Guardar Resultado (Asterisk)","type":"n8n-nodes-base.code","typeVersion":2,"position":[-20800,1072],"disabled":true},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"loose","version":2},"conditions":[{"id":"19137c5d-05f8-4e90-b6dc-c7e8e634506e","leftValue":"={{ $('⚙️ Calcular Providers Activos').first().json.stringee_enabled }}","rightValue":true,"operator":{"type":"boolean","operation":"true","singleValue":true}}],"combinator":"and"},"options":{}},"id":"b0d81bc9-19e1-4fed-a361-36c0b1a52be8","name":"🔀 Stringee Habilitado?","type":"n8n-nodes-base.if","typeVersion":2.2,"position":[-21760,1824],"disabled":true},{"parameters":{"jsCode":"console.log('⏸️ Stringee DESACTIVADO por wf2_provider_config — ciclo omitido');\nreturn [{ json: { skipped: true, provider: 'stringee', at: new Date().toISOString() } }];\n"},"id":"3e0eb18b-4c35-433d-a2da-31d3b842bc65","name":"⏸️ Stringee Desactivado (log)","type":"n8n-nodes-base.code","typeVersion":2,"position":[-21520,1984],"disabled":true},{"parameters":{"jsCode":"const BASE = 'https://lead-studio-9gnl.onrender.com/api';\nconst TOKEN = $('🔐 Login LeadStudio1').first().json.accessToken;\nconst self = this;\n\nasync function api(method, path, opts = {}) {\n  try {\n    const r = await self.helpers.httpRequest({\n      method,\n      url: BASE + path,\n      qs: opts.qs,\n      body: opts.body,\n      json: true,\n      headers: {\n        Authorization: 'Bearer ' + TOKEN,\n        'Content-Type': 'application/json'\n      },\n      returnFullResponse: true,\n      ignoreHttpStatusErrors: true,\n      timeout: 20000\n    });\n\n    return {\n      ok: r.statusCode >= 200 && r.statusCode < 300,\n      status: r.statusCode,\n      body: r.body || {}\n    };\n  } catch (e) {\n    return {\n      ok: false,\n      status: 0,\n      body: {\n        error: String(e.message || e)\n      }\n    };\n  }\n}\n\n// ============================================================================\n// 📥 FETCH + LOCK (STRINGEE)\n//\n// Regla:\n// 3 ciclos x 3 intentos = máximo 9.\n//\n// attempts 0-8  -> puede ir al worker.\n// attempts >= 9 -> NO va al worker.\n//                  status CLOSED.\n//                  stage LOST.\n// ============================================================================\n\nconst MAX_ATTEMPTS = 9;\n\nconst COUNTRIES = [\n  {\n    key: 'india',\n    dialCode: '91',\n    prefix: '+91',\n    batchSize: 3,\n\n    lines: [\n      '917971730907',\n      '917944413269',\n      '917944413268'\n    ],\n\n    fromEnd: true,\n    minDigits: 10,\n    maxDigits: 10,\n    language: 'hi',\n\n    agent_id:\n      'agent_5701kramx550e3qs2tm11661b48p',\n\n    agent_phone_number_id: ''\n  }\n];\n\nconst FETCH_MULT = 3;\n\nfunction normalizePhone(raw, prefix) {\n  let p = String(raw || '')\n    .replace(/[^0-9+]/g, '');\n\n  if (!p) return '';\n\n  if (p.startsWith('+')) {\n    return p;\n  }\n\n  const digits =\n    prefix.replace('+', '');\n\n  if (\n    p.startsWith(digits) &&\n    p.length > digits.length + 6\n  ) {\n    return '+' + p;\n  }\n\n  return prefix + p;\n}\n\nfunction safeAttempts(value) {\n  const n = Number(value);\n\n  if (!Number.isFinite(n) || n < 0) {\n    return 0;\n  }\n\n  return Math.trunc(n);\n}\n\nasync function closeExhaustedLead(\n  leadId,\n  attempts,\n  country\n) {\n  // Primero cerrar.\n  const close = await api(\n    'PATCH',\n    `/leads/${leadId}`,\n    {\n      body: {\n        status: 'CLOSED'\n      }\n    }\n  );\n\n  if (!close.ok) {\n    console.error(\n      `🚨 Stringee ${country}: no se pudo cerrar ${leadId} ` +\n      `con ${attempts} intentos. HTTP ${close.status}. ` +\n      `Por seguridad NO se despacha.`\n    );\n\n    return {\n      closed: false,\n      lost: false\n    };\n  }\n\n  // Después mover a Lost.\n  const lost = await api(\n    'PATCH',\n    `/leads/${leadId}`,\n    {\n      body: {\n        stage: 'LOST'\n      }\n    }\n  );\n\n  if (!lost.ok) {\n    console.error(\n      `⚠️ Stringee ${country}: ${leadId} quedó CLOSED, ` +\n      `pero stage LOST falló HTTP ${lost.status}.`\n    );\n  }\n\n  console.log(\n    `⛔ Stringee ${country}: ${leadId} reached ` +\n    `${attempts}/${MAX_ATTEMPTS} attempts → no dispatch`\n  );\n\n  return {\n    closed: true,\n    lost: lost.ok\n  };\n}\n\nconst out = [];\n\nfor (const c of COUNTRIES) {\n  const limit = Math.min(\n    200,\n    c.batchSize * FETCH_MULT\n  );\n\n  let offset = 0;\n\n  if (c.fromEnd) {\n    const t = await api(\n      'GET',\n      '/leads',\n      {\n        qs: {\n          status: 'NOT_CONTACTED',\n          dialCode: c.dialCode,\n          limit: 1,\n          offset: 0\n        }\n      }\n    );\n\n    offset = t.ok\n      ? Math.max(\n          0,\n          Number(t.body.total || 0) - limit\n        )\n      : 0;\n  }\n\n  const r = await api(\n    'GET',\n    '/leads',\n    {\n      qs: {\n        status: 'NOT_CONTACTED',\n        dialCode: c.dialCode,\n        limit,\n        offset\n      }\n    }\n  );\n\n  if (!r.ok) {\n    console.error(\n      `❌ Stringee ${c.key}: GET /leads falló HTTP ${r.status}`,\n      JSON.stringify(r.body).slice(0, 300)\n    );\n\n    continue;\n  }\n\n  const leads = r.body.leads || [];\n\n  const totalDisponibles =\n    Number(r.body.total || 0);\n\n  let taken = 0;\n  let invalid = 0;\n  let lockFail = 0;\n  let exhausted = 0;\n\n  for (const l of leads) {\n    if (taken >= c.batchSize) break;\n\n    if (!l || !l.id) continue;\n\n    if (\n      String(l.status || '').toUpperCase() !==\n      'NOT_CONTACTED'\n    ) {\n      continue;\n    }\n\n    const currentAttempts =\n      safeAttempts(l.attempts);\n\n    // ==========================================================\n    // HARD LIMIT\n    // No permitir que un lead con 9+ attempts llegue al worker.\n    // ==========================================================\n    if (\n      currentAttempts >=\n      MAX_ATTEMPTS\n    ) {\n      await closeExhaustedLead(\n        l.id,\n        currentAttempts,\n        c.key\n      );\n\n      exhausted++;\n      continue;\n    }\n\n    if (l.doNotCall) {\n      await api(\n        'PATCH',\n        `/leads/${l.id}`,\n        {\n          body: {\n            status: 'CLOSED'\n          }\n        }\n      );\n\n      invalid++;\n      continue;\n    }\n\n    const phone =\n      normalizePhone(\n        l.phone,\n        c.prefix\n      );\n\n    const national =\n      phone.slice(\n        c.prefix.length\n      );\n\n    const validPhone =\n      /^\\+[1-9]\\d{7,14}$/.test(phone) &&\n      phone.startsWith(c.prefix) &&\n      national.length >= c.minDigits &&\n      national.length <= c.maxDigits;\n\n    if (!validPhone) {\n      await api(\n        'PATCH',\n        `/leads/${l.id}`,\n        {\n          body: {\n            status: 'UNREACHABLE'\n          }\n        }\n      );\n\n      console.log(\n        `🚫 ${c.key}: teléfono inválido '${l.phone}' ` +\n        `→ UNREACHABLE (${l.id})`\n      );\n\n      invalid++;\n      continue;\n    }\n\n    // Lock antes de llamar.\n    const lock = await api(\n      'PATCH',\n      `/leads/${l.id}`,\n      {\n        body: {\n          status: 'ATTEMPTING'\n        }\n      }\n    );\n\n    if (!lock.ok) {\n      lockFail++;\n\n      console.error(\n        `🔒❌ ${c.key}: no se pudo bloquear ` +\n        `${l.id} HTTP ${lock.status}`\n      );\n\n      continue;\n    }\n\n    out.push({\n      json: {\n        provider: 'stringee',\n\n        lead_id: l.id,\n\n        full_name:\n          String(l.name || '').trim() ||\n          'User',\n\n        phone,\n\n        country: c.key,\n\n        language:\n          String(\n            l.language ||\n            c.language\n          )\n            .trim()\n            .toLowerCase(),\n\n        call_attempts:\n          currentAttempts,\n\n        _agent_id:\n          c.agent_id,\n\n        _agent_phone_number_id:\n          c.agent_phone_number_id,\n\n        _from_number:\n          c.lines\n            ? c.lines[\n                taken %\n                c.lines.length\n              ]\n            : (\n                c.from_number ||\n                ''\n              )\n      }\n    });\n\n    taken++;\n  }\n\n  const msg =\n    `📥 Stringee ${c.key}: ` +\n    `${totalDisponibles} NOT_CONTACTED | ` +\n    `${leads.length} leídos | ` +\n    `${taken} bloqueados | ` +\n    `${exhausted} agotaron ${MAX_ATTEMPTS} intentos | ` +\n    `${invalid} inválidos | ` +\n    `${lockFail} lock fallidos`;\n\n  if (\n    taken === 0 &&\n    totalDisponibles > 0\n  ) {\n    console.error(\n      '🚨 Hay leads disponibles pero 0 llegaron al batch — ' +\n      msg\n    );\n  } else {\n    console.log(msg);\n  }\n}\n\nreturn out;"},"id":"f96d9ea3-41f3-499c-89ae-bd5d68918dc7","name":"📥 Fetch + Lock (Stringee)","type":"n8n-nodes-base.code","typeVersion":2,"position":[-21520,1792],"disabled":true},{"parameters":{"method":"POST","url":"http://172.18.0.1:8091/call","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Content-Type","value":"application/json"}]},"sendBody":true,"specifyBody":"json","jsonBody":"={\n  \"lead_id\": \"{{ $json.lead_id }}\",\n  \"phone\": \"{{ $json.phone.replace(/^\\+/, '') }}\",\n  \"full_name\": {{ JSON.stringify($json.full_name) }},\n  \"country\": \"{{ $json.country }}\",\n  \"language\": \"{{ $json.language || 'hi' }}\",\n  \"is_followup\": \"{{ $json.call_attempts > 0 ? 'true' : 'false' }}\",\n  \"call_attempts\": {{ Number($json.call_attempts || 0) + 1 }},\n  \"from_number\": \"{{ $json._from_number }}\",\n  \"agent_id\": \"agent_5701kramx550e3qs2tm11661b48p\"\n}","options":{"response":{"response":{"fullResponse":true,"neverError":true,"responseFormat":"json"}},"timeout":45000}},"id":"5689d8e0-f777-49bc-b7e6-57796d7d9efc","name":"📞 POST → Stringee Worker","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[-21280,1792],"disabled":true,"onError":"continueRegularOutput"},{"parameters":{"jsCode":"// ============================================================================\n// 🔍 CLASSIFY RESULT (STRINGEE)\n//\n// IMPORTANTE:\n// Este nodo NO conoce todavía el resultado final de la llamada.\n//\n// El worker solamente confirma que la llamada fue despachada.\n// El resultado final llega por webhook a WF9.\n//\n// Por esa razón:\n// - NO marcar LOST aquí.\n// - NO crear followup aquí.\n// - NO asumir NO_ANSWER.\n// ============================================================================\n\nconst items = $input.all();\n\nconst src =\n  $('📥 Fetch + Lock (Stringee)').all();\n\nconst now =\n  new Date().toISOString();\n\nfunction safeAttempts(value) {\n  const n = Number(value);\n\n  if (!Number.isFinite(n) || n < 0) {\n    return 0;\n  }\n\n  return Math.trunc(n);\n}\n\nfunction pickLead(item, i) {\n  let idx = i;\n\n  const p = item.pairedItem;\n\n  if (\n    p !== undefined &&\n    p !== null\n  ) {\n    const pi = Array.isArray(p)\n      ? p[0]\n      : p;\n\n    if (typeof pi === 'number') {\n      idx = pi;\n    } else if (\n      pi &&\n      typeof pi.item === 'number'\n    ) {\n      idx = pi.item;\n    }\n  }\n\n  return (\n    src[idx] ||\n    src[i] ||\n    src[0]\n  ).json;\n}\n\nreturn items.map(\n  (item, i) => {\n    const lead =\n      pickLead(item, i);\n\n    const resp =\n      item.json || {};\n\n    const statusCode =\n      Number(\n        resp.statusCode ?? 0\n      );\n\n    const body =\n      (\n        resp.body !== undefined\n          ? resp.body\n          : resp\n      ) || {};\n\n    const jobId =\n      String(\n        body.job_id ||\n        body.jobId ||\n        ''\n      );\n\n    const attempts =\n      safeAttempts(\n        lead.call_attempts\n      ) + 1;\n\n    let r;\n\n    // Worker aceptó la llamada.\n    if (\n      statusCode >= 200 &&\n      statusCode < 300 &&\n      body.ok === true &&\n      jobId\n    ) {\n      r = {\n        status: 'ATTEMPTING',\n        attempts,\n        last_call_status:\n          'DISPATCHED',\n\n        // English-only en caso de que en el futuro\n        // esta nota llegue al CRM.\n        notes:\n          'Stringee call dispatched. Worker job: ' +\n          jobId\n      };\n    }\n\n    // Error temporal del proveedor.\n    else if (\n      statusCode === 0 ||\n      statusCode === 429 ||\n      statusCode >= 500\n    ) {\n      r = {\n        status: 'NOT_CONTACTED',\n        attempts: null,\n        last_call_status:\n          'WORKER_ERROR_' +\n          statusCode,\n\n        notes:\n          'Stringee worker unavailable. ' +\n          'The lead was returned to the call queue.'\n      };\n\n      console.error(\n        `🚨 Stringee worker no responde ` +\n        `(HTTP ${statusCode}).`\n      );\n    }\n\n    // Error definitivo al intentar despachar.\n    else {\n      r = {\n        status: 'UNREACHABLE',\n        attempts,\n        last_call_status:\n          statusCode >= 400\n            ? 'HTTP_' + statusCode\n            : 'NO_JOB_ID',\n\n        notes:\n          'Stringee call dispatch failed: ' +\n          JSON.stringify(body)\n            .slice(0, 200)\n      };\n    }\n\n    console.log(\n      '📞 Stringee —',\n      lead.lead_id,\n      '| HTTP',\n      statusCode,\n      '| attempt',\n      attempts,\n      '| →',\n      r.status,\n      '| job:',\n      jobId\n    );\n\n    return {\n      json: {\n        provider: 'stringee',\n\n        lead_id:\n          lead.lead_id,\n\n        country:\n          lead.country,\n\n        job_id:\n          jobId || null,\n\n        last_call_time:\n          now,\n\n        nextFollowUpAt:\n          null,\n\n        outcome:\n          null,\n\n        callStatus:\n          null,\n\n        logFollowup:\n          false,\n\n        ...r\n      }\n    };\n  }\n);"},"id":"c695fa4c-4748-4304-83ee-304a9e3ce85d","name":"🔍 Classify Result (Stringee)","type":"n8n-nodes-base.code","typeVersion":2,"position":[-21040,1792],"disabled":true},{"parameters":{"jsCode":"const BASE =\n  'https://lead-studio-9gnl.onrender.com/api';\n\nconst TOKEN =\n  $('🔐 Login LeadStudio1')\n    .first()\n    .json\n    .accessToken;\n\nconst self = this;\n\nasync function api(\n  method,\n  path,\n  opts = {}\n) {\n  try {\n    const r =\n      await self.helpers.httpRequest({\n        method,\n\n        url:\n          BASE +\n          path,\n\n        qs:\n          opts.qs,\n\n        body:\n          opts.body,\n\n        json:\n          true,\n\n        headers: {\n          Authorization:\n            'Bearer ' +\n            TOKEN,\n\n          'Content-Type':\n            'application/json'\n        },\n\n        returnFullResponse:\n          true,\n\n        ignoreHttpStatusErrors:\n          true,\n\n        timeout:\n          20000\n      });\n\n    return {\n      ok:\n        r.statusCode >= 200 &&\n        r.statusCode < 300,\n\n      status:\n        r.statusCode,\n\n      body:\n        r.body || {}\n    };\n  } catch (e) {\n    return {\n      ok: false,\n\n      status: 0,\n\n      body: {\n        error:\n          String(\n            e.message ||\n            e\n          )\n      }\n    };\n  }\n}\n\n// ============================================================================\n// 🏁 GUARDAR RESULTADO (STRINGEE)\n//\n// Este nodo solamente guarda el estado del DISPATCH.\n//\n// NO crea el resultado final.\n// NO incrementa manualmente attempts.\n// NO crea un NO_ANSWER falso.\n//\n// El resultado final pertenece a WF9.\n// ============================================================================\n\nconst out = [];\n\nlet fails = 0;\n\nfor (\n  const item\n  of $input.all()\n) {\n  const j =\n    item.json || {};\n\n  if (!j.lead_id) {\n    console.error(\n      '❌ Stringee: item sin lead_id'\n    );\n\n    continue;\n  }\n\n  // En esta rama normalmente logFollowup=false.\n  // Se mantiene la compatibilidad por seguridad.\n  let fu = null;\n\n  if (j.logFollowup) {\n    const fuBody = {\n      type: 'CALL',\n      outcome: j.outcome,\n      callStatus: j.callStatus,\n      durationSeconds: 0,\n      notes: j.notes\n    };\n\n    if (\n      j.nextFollowUpAt\n    ) {\n      fuBody.nextActionAt =\n        j.nextFollowUpAt;\n    }\n\n    fu = await api(\n      'POST',\n      `/leads/${j.lead_id}/followups`,\n      {\n        body:\n          fuBody\n      }\n    );\n\n    if (!fu.ok) {\n      console.error(\n        `⚠️ Followup falló ${j.lead_id} ` +\n        `HTTP ${fu.status}`,\n        JSON.stringify(\n          fu.body\n        ).slice(\n          0,\n          200\n        )\n      );\n    }\n  }\n\n  // Solo status, igual que la arquitectura actual.\n  let r =\n    await api(\n      'PATCH',\n      `/leads/${j.lead_id}`,\n      {\n        body: {\n          status:\n            j.status\n        }\n      }\n    );\n\n  if (!r.ok) {\n    r =\n      await api(\n        'PATCH',\n        `/leads/${j.lead_id}`,\n        {\n          body: {\n            status:\n              j.status\n          }\n        }\n      );\n  }\n\n  if (!r.ok) {\n    fails++;\n\n    console.error(\n      `❌ PATCH falló 2 veces ${j.lead_id} ` +\n      `HTTP ${r.status}`,\n      JSON.stringify(\n        r.body\n      ).slice(\n        0,\n        200\n      )\n    );\n  }\n\n  const followupId =\n    fu &&\n    fu.ok &&\n    fu.body &&\n    fu.body.followUp\n      ? fu.body.followUp.id\n      : null;\n\n  out.push({\n    json: {\n      ...j,\n\n      patch_ok:\n        r.ok,\n\n      patch_http:\n        r.status,\n\n      followup_ok:\n        fu\n          ? fu.ok\n          : null,\n\n      followup_id:\n        followupId\n    }\n  });\n}\n\nconsole.log(\n  `🏁 Stringee: ${out.length} guardados | ` +\n  `${fails} PATCH fallidos`\n);\n\nreturn out;"},"id":"49b53353-6e3a-4e31-a42f-4e33cadbbdcd","name":"🏁 Guardar Resultado (Stringee)","type":"n8n-nodes-base.code","typeVersion":2,"position":[-20800,1792],"disabled":true},{"parameters":{"rule":{"interval":[{"field":"minutes"}]}},"id":"0ac9c141-ace0-4d14-95d2-03c01b03b137","name":"⏰ Trigger Mantenimiento (cada 5 min)","type":"n8n-nodes-base.scheduleTrigger","typeVersion":1.3,"position":[-22960,2256],"disabled":true},{"parameters":{"jsCode":"// ============================================================================\n// 🧹 MANTENIMIENTO (cada 5 min) — red de seguridad para que NUNCA quede un lead\n// muerto. Hace su propio login y usa GET /leads con paginación real.\n//  1. ATTEMPTING colgado > STALE_MIN  -> NO_ANSWER con reintento en +2h (no suma intento, no cierra)\n//  2. NO_ANSWER con nextFollowUpAt vencido -> NOT_CONTACTED (vuelve a la cola)\n//  3. Reporta cuántos NOT_CONTACTED hay por país (salud)\n// Primero se juntan TODOS los IDs y recién después se hacen los PATCH, para que\n// la paginación por offset no se corra al ir cambiando estados.\n// ============================================================================\nconst BASE = 'https://lead-studio-9gnl.onrender.com/api';\nconst DIAL_CODES = [{ key: 'india', dialCode: '91' }, { key: 'nepal', dialCode: '977' }];\nconst STALE_MIN = 30;\nconst RETRY_HOURS = 2;   // un ATTEMPTING colgado se reintenta en 2h (igual que el 1er no-answer)\nconst MAX_PAGES = 25;     // hasta 5.000 leads por status/país por corrida\nconst self = this;\nlet TOKEN = '';\n\nasync function api(method, path, opts = {}) {\n  try {\n    const r = await self.helpers.httpRequest({\n      method, url: BASE + path, qs: opts.qs, body: opts.body, json: true,\n      headers: Object.assign({ 'Content-Type': 'application/json' }, TOKEN ? { Authorization: 'Bearer ' + TOKEN } : {}),\n      returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000\n    });\n    return { ok: r.statusCode >= 200 && r.statusCode < 300, status: r.statusCode, body: r.body || {} };\n  } catch (e) { return { ok: false, status: 0, body: { error: String(e.message || e) } }; }\n}\n\nconst login = await api('POST', '/auth/login', { body: { email: 'ai@leadstudio.com', password: 'Admin@123' } });\nif (!login.ok || !login.body.accessToken) {\n  console.error('❌ Mantenimiento: login falló', login.status, JSON.stringify(login.body).slice(0, 200));\n  return [{ json: { error: true, step: 'login', status: login.status } }];\n}\nTOKEN = login.body.accessToken;\n\nasync function listAll(status, dialCode) {\n  const all = []; let offset = 0;\n  for (let p = 0; p < MAX_PAGES; p++) {\n    const r = await api('GET', '/leads', { qs: { status, dialCode, limit: 200, offset } });\n    if (!r.ok) { console.error(`❌ GET /leads ${status} ${dialCode} HTTP ${r.status}`); break; }\n    const leads = r.body.leads || [];\n    all.push(...leads);\n    offset += leads.length;\n    if (leads.length < 200 || offset >= Number(r.body.total || 0)) break;\n  }\n  return all;\n}\nasync function patchMany(list) {\n  let ok = 0, fail = 0;\n  for (let i = 0; i < list.length; i += 10) {\n    const chunk = list.slice(i, i + 10);\n    const res = await Promise.all(chunk.map(x => api('PATCH', `/leads/${x.id}`, { body: x.body })));\n    res.forEach(r => r.ok ? ok++ : fail++);\n  }\n  return { ok, fail };\n}\n\nconst now = new Date();\nconst summary = {};\nfor (const c of DIAL_CODES) {\n  // 1) ATTEMPTING colgados\n  const attempting = await listAll('ATTEMPTING', c.dialCode);\n  const stale = attempting.filter(l => l.status === 'ATTEMPTING' && l.updatedAt &&\n    (now - new Date(l.updatedAt)) > STALE_MIN * 60000);\n  const retryAt = new Date(now.getTime() + RETRY_HOURS * 3600000).toISOString();\n  const staleOps = stale.map(l => ({ id: l.id, body: { status: 'NO_ANSWER', nextFollowUpAt: retryAt } }));\n  const staleRes = await patchMany(staleOps);\n\n  // 2) NO_ANSWER vencidos -> NOT_CONTACTED\n  const noAnswer = await listAll('NO_ANSWER', c.dialCode);\n  const due = noAnswer.filter(l => l.status === 'NO_ANSWER' && l.nextFollowUpAt && new Date(l.nextFollowUpAt) <= now);\n  const dueRes = await patchMany(due.map(l => ({ id: l.id, body: { status: 'NOT_CONTACTED' } })));\n\n  // 3) Salud\n  const h = await api('GET', '/leads', { qs: { status: 'NOT_CONTACTED', dialCode: c.dialCode, limit: 1, offset: 0 } });\n  const disponibles = h.ok ? Number(h.body.total || 0) : null;\n\n  summary[c.key] = {\n    attempting_total: attempting.length,\n    attempting_liberados: staleRes.ok,\n    no_answer_total: noAnswer.length, no_answer_reactivados: dueRes.ok,\n    patch_fallidos: staleRes.fail + dueRes.fail,\n    not_contacted_disponibles: disponibles\n  };\n  console.log(`🧹 ${c.key}:`, JSON.stringify(summary[c.key]));\n  if (disponibles === 0) console.error(`🚨 ${c.key}: 0 leads NOT_CONTACTED — el dialer no tiene a quién llamar`);\n}\nreturn [{ json: { ran_at: now.toISOString(), ...summary } }];\n"},"id":"8eb99e3c-f050-4afa-9919-ddf625703a01","name":"🧹 Mantenimiento Leads (reactivar + liberar)","type":"n8n-nodes-base.code","typeVersion":2,"position":[-22720,2256],"disabled":true},{"parameters":{"content":"### 📞 WF2 UNIFICADO v2 — Asterisk + Stringee (rediseño 24/09/2026)\n\n**Incidente 24/09:** `/leads/queue` devuelve siempre la misma ventana, con follow-ups vencidos (ATTEMPTING/CONTACTED) primero. El filtro exigía NOT_CONTACTED → los descartaba, nunca se tocaban y **bloquearon la cabeza de la cola** con 17k leads disponibles detrás. ~4h sin llamadas.\n\n**Reglas del v2 (no romper):**\n1. Leer SIEMPRE `GET /leads?status=NOT_CONTACTED&dialCode=X` — NO `/leads/queue`.\n2. Lock `PATCH → ATTEMPTING` ANTES de llamar; solo se llama si el lock OK.\n3. Lead inválido (teléfono / doNotCall) se saca del pool → nunca tapa la cola.\n4. Error del proveedor (key, créditos, 429, 5xx, worker caído) → lead vuelve a NOT_CONTACTED sin sumar intento.\n5. 🧹 Mantenimiento cada 5 min: ATTEMPTING > 30 min → NO_ANSWER (+2h); NO_ANSWER vencido → NOT_CONTACTED.\n7. Asterisk toma India desde el principio de la lista y Stringee desde el final → no se pisan.\n6. Logs con 🚨 = revisar ya (0 al batch habiendo disponibles, proveedor caído, 0 disponibles).\n\n`/leads/queue` solo acepta `limit` (1–200) y `dialCode`. `/leads` acepta `status`, `dialCode`, `limit`, `offset`.","height":460,"width":620,"color":4},"id":"1d9fa46b-931a-442c-888b-8e1bf6a20070","name":"🧭 Nota — Diseño v2","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[-23024,832],"disabled":true},{"parameters":{"method":"POST","url":"https://lead-studio-9gnl.onrender.com/api/auth/login","sendBody":true,"specifyBody":"json","jsonBody":"={\n  \"email\": \"ai@leadstudio.com\",\n  \"password\": \"Admin@123\"\n}","options":{"response":{"response":{"neverError":true,"responseFormat":"json"}},"timeout":15000}},"id":"e22abd46-1d9d-4254-b590-42613e0c2288","name":"🔐 Login LeadStudio1","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[-22240,1392],"retryOnFail":true,"maxTries":3,"waitBetweenTries":2000,"disabled":true},{"parameters":{"operation":"executeQuery","query":"SELECT 'ok' AS kind, NULL AS lead_id, COUNT(*) AS n, NULL AS hold_ms, NULL AS set_ms FROM wf_call_events UNION ALL SELECT 'unresolved', lead_id, COUNT(*), NULL, MIN(TIMESTAMPDIFF(MICROSECOND, '1970-01-01 00:00:00', COALESCE(dispatched_at, first_seen_at)) DIV 1000) FROM wf_call_events WHERE (source = 'stringee' OR (source = 'elevenlabs' AND provider = 'asterisk' AND dispatched_at IS NOT NULL)) AND state IN ('RECEIVED', 'PROCESSING', 'FAILED') AND lead_id IS NOT NULL GROUP BY lead_id UNION ALL SELECT 'hold', e.lead_id, 1, TIMESTAMPDIFF(MICROSECOND, '1970-01-01 00:00:00', e.next_retry_at) DIV 1000, TIMESTAMPDIFF(MICROSECOND, '1970-01-01 00:00:00', e.processed_at) DIV 1000 FROM wf_call_events e JOIN (SELECT lead_id, MAX(event_at) AS mx FROM wf_call_events WHERE lifecycle_applied = 1 AND lead_id IS NOT NULL AND event_at IS NOT NULL GROUP BY lead_id) m ON m.lead_id = e.lead_id AND m.mx = e.event_at WHERE e.lifecycle_applied = 1 AND e.next_retry_at IS NOT NULL UNION ALL SELECT 'stuck', NULL, COUNT(*), NULL, NULL FROM wf_call_events WHERE state = 'FAILED' AND error_count >= 5","options":{}},"name":"🗄️ Leer Estado Eventos (Mantenimiento)","type":"n8n-nodes-base.mySql","typeVersion":2.4,"position":[-17392,2176],"alwaysOutputData":true,"id":"c44cd5b6-de6d-47fd-bb28-2e4f9e00c1cf","credentials":{"mySql":{"id":"4NiWyzzJ4JbMkIjT","name":"MySQL account"}},"onError":"continueRegularOutput"},{"parameters":{"jsCode":"// ============================================================================\n// 🧾 BUILD LEDGER SQL (STRINGEE) — registro durable de cada job despachado.\n// Sólo para jobs aceptados por el worker (job_id válido). WF9 reconcilia cada\n// job con GET /calls/:job_id aunque el callback del worker se pierda.\n// No cambia nada del despacho: corre DESPUÉS de 🏁 Guardar Resultado (Stringee).\n// Horas en UTC explícito.\n// ============================================================================\nconst UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;\nfunction q(v) {\n  if (v === null || v === undefined || v === '') return 'NULL';\n  if (typeof v === 'number') return Number.isFinite(v) ? String(Math.trunc(v)) : 'NULL';\n  return \"'\" + String(v).replace(/\\u0000/g, '').replace(/[\\r\\n]+/g, ' ').replace(/\\$/g, '').replace(/\\\\/g, '\\\\\\\\').replace(/'/g, \"''\")\n    .replace(/\\{\\{/g, '{ {').replace(/\\}\\}/g, '} }') + \"'\";\n}\nfunction dt(v) {\n  const t = v ? new Date(v).getTime() : NaN;\n  return Number.isFinite(t) ? \"'\" + new Date(t).toISOString().replace('T', ' ').replace('Z', '') + \"'\" : 'UTC_TIMESTAMP(3)';\n}\nconst locked = $('📥 Fetch + Lock (Stringee)1').all().map(i => i.json || {});\nconst phoneOf = id => { const l = locked.find(x => x.lead_id === id); return l ? String(l.phone || '').replace(/\\D/g, '') : null; };\nconst rows = [];\nfor (const it of $input.all()) {\n  const j = it.json || {};\n  const jobId = String(j.job_id || '');\n  if (!UUID_RE.test(jobId) || !j.lead_id) continue;\n  const att = Number(j.attempts);\n  rows.push('(' + [q('stringee:' + jobId), q('stringee'), q('stringee'), q(jobId), q(String(j.lead_id).slice(0, 64)),\n    q(phoneOf(j.lead_id)), q(Number.isInteger(att) && att >= 1 && att <= 99 ? att : null),\n    dt(j.last_call_time), dt(j.last_call_time), 'UTC_TIMESTAMP(3)', q('RECEIVED'),\n    'UTC_TIMESTAMP(3) + INTERVAL 3 MINUTE', q(JSON.stringify({ via: 'wf2_dispatch', patch_ok: j.patch_ok === true }))].join(', ') + ')');\n}\nif (!rows.length) return [{ json: { ledger_rows: 0, ledger_sql: 'SELECT 1 AS noop' } }];\nconst ledger_sql = 'INSERT INTO wf_call_events (event_key, source, provider, external_id, lead_id, phone, call_attempts, ' +\n  'event_at, dispatched_at, first_seen_at, state, next_attempt_at, payload) VALUES ' + rows.join(', ') +\n  ' ON DUPLICATE KEY UPDATE provider = COALESCE(provider, VALUES(provider)), lead_id = COALESCE(lead_id, VALUES(lead_id)), ' +\n  'phone = COALESCE(phone, VALUES(phone)), call_attempts = COALESCE(call_attempts, VALUES(call_attempts)), ' +\n  'event_at = COALESCE(event_at, VALUES(event_at)), dispatched_at = COALESCE(dispatched_at, VALUES(dispatched_at))';\nconsole.log(`🧾 Ledger Stringee: ${rows.length} job(s) registrados para reconciliación`);\nreturn [{ json: { ledger_rows: rows.length, ledger_sql } }];\n"},"name":"🧾 Build Ledger SQL (Stringee)","type":"n8n-nodes-base.code","typeVersion":2,"position":[-15232,1712],"id":"cafd620a-911b-4a4c-952c-3af5c6238c0f"},{"parameters":{"operation":"executeQuery","query":"{{ $json.ledger_sql }}","options":{}},"name":"💾 Ledger Dispatch (Stringee)","type":"n8n-nodes-base.mySql","typeVersion":2.4,"position":[-14992,1712],"retryOnFail":true,"maxTries":3,"waitBetweenTries":1000,"id":"e1f5eb5f-6573-4ccd-8ca6-ae6c259d4e63","credentials":{"mySql":{"id":"4NiWyzzJ4JbMkIjT","name":"MySQL account"}}},{"parameters":{"jsCode":"// ============================================================================\n// 🧾 BUILD FOLLOWUP ROW (ASTERISK) — fila en wf_call_followups para cada\n// Activity que WF2 creó (la usa WF10 para subir la grabación).\n// recording_synced = 0 si la llamada fue CONNECTED (hay grabación que subir),\n// 1 si no se espera grabación. Idempotente por followup_id.\n// No cambia nada del flujo Asterisk: corre DESPUÉS de 🏁 Guardar Resultado (Asterisk).\n// ============================================================================\nfunction q(v) {\n  if (v === null || v === undefined) return 'NULL';\n  if (typeof v === 'number') return Number.isFinite(v) ? String(Math.trunc(v)) : 'NULL';\n  return \"'\" + String(v).replace(/\\u0000/g, '').replace(/[\\r\\n]+/g, ' ').replace(/\\$/g, '').replace(/\\\\/g, '\\\\\\\\').replace(/'/g, \"''\")\n    .replace(/\\{\\{/g, '{ {').replace(/\\}\\}/g, '} }') + \"'\";\n}\nconst locked = $('📥 Fetch + Lock (Asterisk)1').all().map(i => i.json || {});\nconst out = [];\nfor (const it of $input.all()) {\n  const j = it.json || {};\n  if (!j.followup_id || !j.lead_id) continue;\n  const l = locked.find(x => x.lead_id === j.lead_id) || {};\n  const phone = String(l.phone || '').replace(/[^0-9+]/g, '').slice(0, 20);\n  const synced = String(j.outcome || '').toUpperCase() === 'CONNECTED' ? 0 : 1;\n  out.push('INSERT INTO wf_call_followups (phone, lead_id, followup_id, provider, outcome, call_status, recording_synced) SELECT ' +\n    [q(phone), q(String(j.lead_id)), q(String(j.followup_id)), q('asterisk'), q(j.outcome || null), q(j.callStatus || null), q(synced)].join(', ') +\n    ' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM wf_call_followups WHERE followup_id = ' + q(String(j.followup_id)) + ')');\n}\nif (!out.length) return [{ json: { rows: 0, fcf_sql: 'SELECT 1 AS noop' } }];\nconsole.log(`🧾 wf_call_followups Asterisk: ${out.length} fila(s)`);\nreturn out.map(s => ({ json: { rows: 1, fcf_sql: s } }));\n"},"name":"🧾 Build Followup Row (Asterisk)","type":"n8n-nodes-base.code","typeVersion":2,"position":[-15232,992],"id":"a05161fc-177a-47c2-9052-1955a66f472d"},{"parameters":{"operation":"executeQuery","query":"{{ $json.fcf_sql }}","options":{}},"name":"💾 Save Followup ID (Asterisk)","type":"n8n-nodes-base.mySql","typeVersion":2.4,"position":[-14992,992],"retryOnFail":true,"maxTries":2,"waitBetweenTries":1000,"id":"2ce425d3-0d44-46b2-9446-3c69a7e73fa4","credentials":{"mySql":{"id":"4NiWyzzJ4JbMkIjT","name":"MySQL account"}},"onError":"continueRegularOutput"},{"parameters":{"rule":{"interval":[{"field":"minutes","minutesInterval":1}]}},"id":"07bec667-5313-4a70-8159-9c1f84f6b3be","name":"⏰ Trigger Dialer (cada 1 min)1","type":"n8n-nodes-base.scheduleTrigger","typeVersion":1.3,"position":[-17632,1312]},{"parameters":{"httpMethod":"POST","path":"dial-now-unificado-v2","options":{}},"id":"c2deb9db-d46d-4e4b-9c0f-fbf25e2e9947","name":"🪝 Manual Trigger (test manual)3","webhookId":"dial-now-unificado-v2","type":"n8n-nodes-base.webhook","typeVersion":2,"position":[-17632,1520],"disabled":true},{"parameters":{"operation":"executeQuery","query":"SELECT provider, enabled FROM wf2_provider_config;","options":{}},"id":"d882d9a7-44d6-4fa7-9770-3151cda11dc0","name":"🗄️ Leer Providers Activos (MySQL)3","type":"n8n-nodes-base.mySql","typeVersion":2.4,"position":[-17392,1312],"alwaysOutputData":true,"credentials":{"mySql":{"id":"4NiWyzzJ4JbMkIjT","name":"MySQL account"}},"onError":"continueRegularOutput"},{"parameters":{"jsCode":"// Lee wf2_provider_config. Fail-open: si falta la tabla/fila, el proveedor queda HABILITADO.\nconst rows = $input.all().map(i => i.json).filter(r => r && r.provider);\nfunction isEnabled(name) {\n  const row = rows.find(r => String(r.provider).toLowerCase() === name);\n  if (!row) return true;\n  return Number(row.enabled) === 1;\n}\nconst asterisk_enabled = isEnabled('asterisk');\nconst stringee_enabled = isEnabled('stringee');\nconsole.log('🔀 Providers —', 'Asterisk:', asterisk_enabled, '| Stringee:', stringee_enabled);\nreturn [{ json: { asterisk_enabled, stringee_enabled } }];\n"},"id":"02db743e-2c31-416b-af62-fadd825d5f40","name":"⚙️ Calcular Providers Activos3","type":"n8n-nodes-base.code","typeVersion":2,"position":[-17152,1312]},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"loose","version":2},"conditions":[{"id":"2e580fa3-94a3-4db3-9217-083c797b7c05","leftValue":"={{ $json.accessToken || '' }}","rightValue":"","operator":{"type":"string","operation":"notEmpty","singleValue":true}}],"combinator":"and"},"options":{}},"id":"aef31996-2016-4dcc-b4e3-be813a6ea0e4","name":"✅ Token OK?3","type":"n8n-nodes-base.if","typeVersion":2.2,"position":[-16672,1312]},{"parameters":{"jsCode":"const resp = $('🔐 Login LeadStudio3').first().json;\nconsole.error('❌ WF2: Login a LeadStudio falló', JSON.stringify(resp).slice(0, 500));\nreturn [{ json: { error: true, message: 'LeadStudio auth failed', response: resp } }];\n"},"id":"417089cd-fbb4-4999-a56b-6afc59c2f8f9","name":"❌ Log Auth Error3","type":"n8n-nodes-base.code","typeVersion":2,"position":[-16432,1472]},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"loose","version":2},"conditions":[{"id":"4c89d07a-0221-4e58-8616-693fa1ff6f0d","leftValue":"={{ $('⚙️ Calcular Providers Activos3').first().json.asterisk_enabled }}","rightValue":true,"operator":{"type":"boolean","operation":"true","singleValue":true}}],"combinator":"and"},"options":{}},"id":"aea72ded-e500-4635-8821-dec70fc8a5cd","name":"🔀 Asterisk Habilitado?3","type":"n8n-nodes-base.if","typeVersion":2.2,"position":[-16432,1072]},{"parameters":{"jsCode":"console.log('⏸️ Asterisk DESACTIVADO por wf2_provider_config — ciclo omitido');\nreturn [{ json: { skipped: true, provider: 'asterisk', at: new Date().toISOString() } }];\n"},"id":"7f5304a4-ae43-43b8-99c8-4be1db77fe23","name":"⏸️ Asterisk Desactivado (log)3","type":"n8n-nodes-base.code","typeVersion":2,"position":[-16192,1232]},{"parameters":{"jsCode":"const BASE = 'https://lead-studio-9gnl.onrender.com/api';\nconst TOKEN = $('🔐 Login LeadStudio3').first().json.accessToken;\nconst self = this;\n\nasync function api(method, path, opts = {}) {\n  try {\n    const r = await self.helpers.httpRequest({\n      method,\n      url: BASE + path,\n      qs: opts.qs,\n      body: opts.body,\n      json: true,\n      headers: {\n        Authorization: 'Bearer ' + TOKEN,\n        'Content-Type': 'application/json'\n      },\n      returnFullResponse: true,\n      ignoreHttpStatusErrors: true,\n      timeout: 20000\n    });\n\n    return {\n      ok: r.statusCode >= 200 && r.statusCode < 300,\n      status: r.statusCode,\n      body: r.body || {}\n    };\n  } catch (e) {\n    return {\n      ok: false,\n      status: 0,\n      body: { error: String(e.message || e) }\n    };\n  }\n}\n\n// ============================================================================\n// 📥 FETCH + LOCK (ASTERISK)\n//\n// Regla:\n// 3 ciclos x 3 intentos = máximo 9.\n//\n// attempts 0-8  -> puede despacharse.\n// attempts >= 9 -> NO se despacha.\n//                  status CLOSED.\n//                  stage UNRESPONSIVE.\n//\n// El bloqueo ocurre ANTES de ElevenLabs.\n// ============================================================================\n\nconst MAX_ATTEMPTS = 9;\n\nconst COUNTRIES = [\n  {\n    key: 'india',\n    dialCode: '91',\n    prefix: '+91',\n    batchSize: 5,\n    minDigits: 10,\n    maxDigits: 10,\n    language: 'hi',\n    agent_id: 'agent_5701kramx550e3qs2tm11661b48p',\n    agent_phone_number_id: 'phnum_7801kyktmabxembteqce884tanb6'\n  },\n  {\n    key: 'nepal',\n    dialCode: '977',\n    prefix: '+977',\n    batchSize: 6,\n    minDigits: 8,\n    maxDigits: 10,\n    language: 'hi',\n    agent_id: 'agent_7601m209ntj3fyrbg0dcq6w507yq',\n    agent_phone_number_id: 'phnum_7801kyktmabxembteqce884tanb6'\n  }\n];\n\nconst FETCH_MULT = 3;\n\nfunction normalizePhone(raw, prefix) {\n  let p = String(raw || '').replace(/[^0-9+]/g, '');\n\n  if (!p) return '';\n\n  if (p.startsWith('+')) return p;\n\n  const digits = prefix.replace('+', '');\n\n  if (\n    p.startsWith(digits) &&\n    p.length > digits.length + 6\n  ) {\n    return '+' + p;\n  }\n\n  return prefix + p;\n}\n\nfunction safeAttempts(value) {\n  const n = Number(value);\n\n  if (!Number.isFinite(n) || n < 0) {\n    return 0;\n  }\n\n  return Math.trunc(n);\n}\n\n// Cierra un lead agotado.\n// Primero CLOSED para impedir nuevas llamadas.\n// Después intenta mover el stage a UNRESPONSIVE.\nasync function closeExhaustedLead(leadId, attempts, country) {\n  const close = await api(\n    'PATCH',\n    `/leads/${leadId}`,\n    {\n      body: {\n        status: 'CLOSED'\n      }\n    }\n  );\n\n  if (!close.ok) {\n    console.error(\n      `🚨 Asterisk ${country}: no se pudo cerrar ${leadId} ` +\n      `con ${attempts} intentos. HTTP ${close.status}. ` +\n      `Por seguridad NO se despacha.`\n    );\n\n    return {\n      closed: false,\n      lost: false\n    };\n  }\n\n  const lost = await api(\n    'PATCH',\n    `/leads/${leadId}`,\n    {\n      body: {\n        stage: 'UNRESPONSIVE'\n      }\n    }\n  );\n\n  if (!lost.ok) {\n    console.error(\n      `⚠️ Asterisk ${country}: ${leadId} quedó CLOSED, ` +\n      `pero stage UNRESPONSIVE falló HTTP ${lost.status}.`\n    );\n  }\n\n  console.log(\n    `⛔ Asterisk ${country}: ${leadId} reached ` +\n    `${attempts}/${MAX_ATTEMPTS} attempts → no dispatch`\n  );\n\n  return {\n    closed: true,\n    lost: lost.ok\n  };\n}\n\nconst out = [];\n\nfor (const c of COUNTRIES) {\n  const limit = Math.min(\n    200,\n    c.batchSize * FETCH_MULT\n  );\n\n  let offset = 0;\n\n  if (c.fromEnd) {\n    const t = await api(\n      'GET',\n      '/leads',\n      {\n        qs: {\n          status: 'NOT_CONTACTED',\n          dialCode: c.dialCode,\n          limit: 1,\n          offset: 0\n        }\n      }\n    );\n\n    offset = t.ok\n      ? Math.max(\n          0,\n          Number(t.body.total || 0) - limit\n        )\n      : 0;\n  }\n\n  const r = await api(\n    'GET',\n    '/leads',\n    {\n      qs: {\n        status: 'NOT_CONTACTED',\n        dialCode: c.dialCode,\n        limit,\n        offset\n      }\n    }\n  );\n\n  if (!r.ok) {\n    console.error(\n      `❌ Asterisk ${c.key}: GET /leads falló HTTP ${r.status}`,\n      JSON.stringify(r.body).slice(0, 300)\n    );\n\n    continue;\n  }\n\n  const leads = r.body.leads || [];\n  const totalDisponibles = Number(r.body.total || 0);\n\n  let taken = 0;\n  let invalid = 0;\n  let lockFail = 0;\n  let exhausted = 0;\n\n  for (const l of leads) {\n    if (taken >= c.batchSize) break;\n\n    if (!l || !l.id) continue;\n\n    if (\n      String(l.status || '').toUpperCase() !== 'NOT_CONTACTED'\n    ) {\n      continue;\n    }\n\n    const currentAttempts = safeAttempts(l.attempts);\n\n    // ==========================================================\n    // HARD LIMIT\n    // Si ya tiene 9 intentos o más, nunca llega a ElevenLabs.\n    // ==========================================================\n    if (currentAttempts >= MAX_ATTEMPTS) {\n      await closeExhaustedLead(\n        l.id,\n        currentAttempts,\n        c.key\n      );\n\n      exhausted++;\n      continue;\n    }\n\n    if (l.doNotCall) {\n      await api(\n        'PATCH',\n        `/leads/${l.id}`,\n        {\n          body: {\n            status: 'CLOSED'\n          }\n        }\n      );\n\n      invalid++;\n      continue;\n    }\n\n    const phone = normalizePhone(\n      l.phone,\n      c.prefix\n    );\n\n    const national = phone.slice(\n      c.prefix.length\n    );\n\n    const validPhone =\n      /^\\+[1-9]\\d{7,14}$/.test(phone) &&\n      phone.startsWith(c.prefix) &&\n      national.length >= c.minDigits &&\n      national.length <= c.maxDigits;\n\n    if (!validPhone) {\n      await api(\n        'PATCH',\n        `/leads/${l.id}`,\n        {\n          body: {\n            status: 'UNREACHABLE'\n          }\n        }\n      );\n\n      console.log(\n        `🚫 ${c.key}: teléfono inválido '${l.phone}' ` +\n        `→ UNREACHABLE (${l.id})`\n      );\n\n      invalid++;\n      continue;\n    }\n\n    // Lock antes de llamar.\n    const lock = await api(\n      'PATCH',\n      `/leads/${l.id}`,\n      {\n        body: {\n          status: 'ATTEMPTING'\n        }\n      }\n    );\n\n    if (!lock.ok) {\n      lockFail++;\n\n      console.error(\n        `🔒❌ ${c.key}: no se pudo bloquear ${l.id} ` +\n        `HTTP ${lock.status}`\n      );\n\n      continue;\n    }\n\n    out.push({\n      json: {\n        provider: 'asterisk',\n        lead_id: l.id,\n        full_name:\n          String(l.name || '').trim() || 'User',\n        phone,\n        country: c.key,\n        language:\n          String(l.language || c.language)\n            .trim()\n            .toLowerCase(),\n\n        call_attempts: currentAttempts,\n\n        _agent_id: c.agent_id,\n        _agent_phone_number_id:\n          c.agent_phone_number_id,\n\n        _from_number: c.lines\n          ? c.lines[taken % c.lines.length]\n          : (c.from_number || '')\n      }\n    });\n\n    taken++;\n  }\n\n  const msg =\n    `📥 Asterisk ${c.key}: ` +\n    `${totalDisponibles} NOT_CONTACTED | ` +\n    `${leads.length} leídos | ` +\n    `${taken} bloqueados | ` +\n    `${exhausted} agotaron ${MAX_ATTEMPTS} intentos | ` +\n    `${invalid} inválidos | ` +\n    `${lockFail} lock fallidos`;\n\n  if (\n    taken === 0 &&\n    totalDisponibles > 0\n  ) {\n    console.error(\n      '🚨 Hay leads disponibles pero 0 llegaron al batch — ' +\n      msg\n    );\n  } else {\n    console.log(msg);\n  }\n}\n\nreturn out;"},"id":"a2696905-c2a3-4ec0-b961-bd039f28ba67","name":"📥 Fetch + Lock (Asterisk)1","type":"n8n-nodes-base.code","typeVersion":2,"position":[-16192,992]},{"parameters":{"method":"POST","url":"https://api.elevenlabs.io/v1/convai/sip-trunk/outbound-call","authentication":"genericCredentialType","genericAuthType":"httpHeaderAuth","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Content-Type","value":"application/json"},{"name":"xi-api-key","value":"sk_79048a9776812db4416e5c690d0c047132d565fee7d43acd"}]},"sendBody":true,"specifyBody":"json","jsonBody":"={\n  \"agent_id\": \"{{ $json._agent_id }}\",\n  \"agent_phone_number_id\": \"{{ $json._agent_phone_number_id }}\",\n  \"to_number\": \"{{ $json.phone }}\",\n  \"conversation_initiation_client_data\": {\n    \"conversation_config_override\": {\n      \"agent\": { \"language\": \"{{ $json.language }}\" }\n    },\n    \"dynamic_variables\": {\n      \"lead_id\": \"{{ $json.lead_id }}\",\n      \"full_name\": {{ JSON.stringify($json.full_name) }},\n      \"phone\": \"{{ $json.phone }}\",\n      \"country\": \"{{ $json.country }}\",\n      \"language\": \"{{ $json.language }}\",\n      \"is_followup\": \"{{ $json.call_attempts > 0 ? 'true' : 'false' }}\",\n      \"call_attempts\": \"{{ Number($json.call_attempts || 0) + 1 }}\"\n    }\n  }\n}","options":{"batching":{"batch":{"batchSize":5,"batchInterval":0}},"response":{"response":{"fullResponse":true,"neverError":true,"responseFormat":"json"}},"timeout":60000}},"id":"c1c22689-6da1-4973-a1eb-17cfb6992b88","name":"📞 POST → ElevenLabs Dial (Asterisk)3","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[-15952,992],"credentials":{"httpHeaderAuth":{"id":"ui7o7nfbbbmdISf2","name":"Header Auth account"}},"onError":"continueRegularOutput"},{"parameters":{"jsCode":"// ============================================================================\n// 🔍 CLASSIFY DIAL RESULT (ASTERISK)\n//\n// CRM visible text: ENGLISH ONLY.\n// Comentarios/logs internos: español.\n//\n// Ciclo 1: attempts 1-3\n// Ciclo 2: attempts 4-6\n// Ciclo 3: attempts 7-9\n//\n// Attempt 9 + NO_ANSWER -> CLOSED + UNRESPONSIVE.\n// ============================================================================\n\nconst items = $input.all();\nconst src = $('📥 Fetch + Lock (Asterisk)1').all();\n\nconst nowDate = new Date();\n\nconst NO_ANSWER_CODES = [\n  '603',\n  '408',\n  '486'\n];\n\nconst MAX_ATTEMPTS = 9;\nconst ATTEMPTS_PER_CYCLE = 3;\nconst MAX_CYCLES = 3;\n\nfunction addHours(d, h) {\n  return new Date(\n    d.getTime() + h * 3600000\n  ).toISOString();\n}\n\nfunction addBusinessDays(d, days) {\n  const r = new Date(d.getTime());\n  let added = 0;\n\n  while (added < days) {\n    r.setDate(r.getDate() + 1);\n\n    const weekday = r.getDay();\n\n    if (\n      weekday !== 0 &&\n      weekday !== 6\n    ) {\n      added++;\n    }\n  }\n\n  return r.toISOString();\n}\n\nfunction safeAttempts(value) {\n  const n = Number(value);\n\n  if (!Number.isFinite(n) || n < 0) {\n    return 0;\n  }\n\n  return Math.trunc(n);\n}\n\nfunction pickLead(item, i) {\n  let idx = i;\n\n  const p = item.pairedItem;\n\n  if (\n    p !== undefined &&\n    p !== null\n  ) {\n    const pi = Array.isArray(p)\n      ? p[0]\n      : p;\n\n    if (typeof pi === 'number') {\n      idx = pi;\n    } else if (\n      pi &&\n      typeof pi.item === 'number'\n    ) {\n      idx = pi.item;\n    }\n  }\n\n  return (\n    src[idx] ||\n    src[i] ||\n    src[0]\n  ).json;\n}\n\nfunction isProviderFail(httpStatus, message) {\n  if (\n    httpStatus === 0 ||\n    httpStatus === 401 ||\n    httpStatus === 402 ||\n    httpStatus === 403 ||\n    httpStatus === 429 ||\n    httpStatus >= 500\n  ) {\n    return true;\n  }\n\n  return /concurren|rate.?limit|quota|credit|insufficient|too many/i.test(\n    message\n  );\n}\n\nlet providerFails = 0;\n\nconst out = items.map((item, i) => {\n  const lead = pickLead(item, i);\n\n  const resp = item.json || {};\n\n  const httpStatus = Number(\n    resp.statusCode ?? 0\n  );\n\n  const body =\n    (\n      resp.body !== undefined\n        ? resp.body\n        : resp\n    ) || {};\n\n  const detail = body.detail;\n\n  let message =\n    body.message ||\n    (\n      detail &&\n      (\n        typeof detail === 'string'\n          ? detail\n          : (\n              detail.message ||\n              JSON.stringify(detail)\n            )\n      )\n    ) ||\n    body.error ||\n    resp.error ||\n    '';\n\n  if (typeof message !== 'string') {\n    message = JSON.stringify(message);\n  }\n\n  const conversationId =\n    body.conversation_id || '';\n\n  const success =\n    body.success === true;\n\n  const sipMatch =\n    message.match(/SIP\\s*(\\d{3})/i) ||\n    message.match(/\\b(\\d{3})\\b/);\n\n  const sipCode = sipMatch\n    ? sipMatch[1]\n    : null;\n\n  const isNoAnswer =\n    !!sipCode &&\n    NO_ANSWER_CODES.includes(sipCode);\n\n  const previousAttempts =\n    safeAttempts(lead.call_attempts);\n\n  const attempts =\n    previousAttempts + 1;\n\n  let r;\n\n  // ==========================================================\n  // ANSWERED\n  // Aunque sea attempt 9, si contestó NO va a UNRESPONSIVE.\n  // ==========================================================\n  if (\n    success &&\n    conversationId\n  ) {\n    r = {\n      status: 'CONTACTED',\n      stage: null,\n      attempts,\n      nextFollowUpAt: null,\n      last_call_status: 'ANSWERED',\n      outcome: 'CONNECTED',\n      callStatus: 'ANSWERED',\n      notes:\n        'Call connected successfully: ' +\n        conversationId,\n      logFollowup: true\n    };\n  }\n\n  // ==========================================================\n  // NO ANSWER\n  // ==========================================================\n  else if (isNoAnswer) {\n    const pos =\n      ((attempts - 1) % ATTEMPTS_PER_CYCLE) + 1;\n\n    const cycle =\n      Math.ceil(\n        attempts / ATTEMPTS_PER_CYCLE\n      );\n\n    let status = 'NO_ANSWER';\n    let stage = null;\n    let next = null;\n    let notes = '';\n\n    // Intento 9 = fin definitivo.\n    if (attempts >= MAX_ATTEMPTS) {\n      status = 'CLOSED';\n      stage = 'UNRESPONSIVE';\n      next = null;\n\n      notes =\n        `No answer (SIP ${sipCode}) — ` +\n        `end of cycle ${MAX_CYCLES} (3/3) — ` +\n        `maximum ${MAX_ATTEMPTS} call attempts reached.`;\n    }\n\n    else if (pos === 1) {\n      next = addHours(\n        nowDate,\n        2\n      );\n\n      notes =\n        `No answer (SIP ${sipCode}) — ` +\n        `attempt ${attempts} ` +\n        `(cycle ${cycle}, 1/3) — ` +\n        `next attempt in 2 hours.`;\n    }\n\n    else if (pos === 2) {\n      next = addHours(\n        nowDate,\n        3\n      );\n\n      notes =\n        `No answer (SIP ${sipCode}) — ` +\n        `attempt ${attempts} ` +\n        `(cycle ${cycle}, 2/3) — ` +\n        `next attempt in 3 hours.`;\n    }\n\n    else if (cycle === 1) {\n      next = addBusinessDays(\n        nowDate,\n        2\n      );\n\n      notes =\n        `No answer (SIP ${sipCode}) — ` +\n        `end of cycle 1 (3/3) — ` +\n        `next cycle in 2 business days.`;\n    }\n\n    else if (cycle === 2) {\n      next = addBusinessDays(\n        nowDate,\n        3\n      );\n\n      notes =\n        `No answer (SIP ${sipCode}) — ` +\n        `end of cycle 2 (3/3) — ` +\n        `next cycle in 3 business days.`;\n    }\n\n    else {\n      // Defensa extra. No debería alcanzarse.\n      status = 'CLOSED';\n      stage = 'UNRESPONSIVE';\n      next = null;\n\n      notes =\n        `No answer (SIP ${sipCode}) — ` +\n        `maximum ${MAX_ATTEMPTS} call attempts reached.`;\n    }\n\n    r = {\n      status,\n      stage,\n      attempts,\n      nextFollowUpAt: next,\n      last_call_status:\n        'NO_ANSWER_SIP_' + sipCode,\n      outcome: 'NO_ANSWER',\n      callStatus: 'NO_ANSWER',\n      notes,\n      logFollowup: true\n    };\n  }\n\n  // ==========================================================\n  // ERROR DEL PROVEEDOR\n  // No consume intento.\n  // ==========================================================\n  else if (\n    isProviderFail(\n      httpStatus,\n      message\n    )\n  ) {\n    providerFails++;\n\n    r = {\n      status: 'NOT_CONTACTED',\n      stage: null,\n      attempts: null,\n      nextFollowUpAt: null,\n      last_call_status:\n        'PROVIDER_ERROR_' + httpStatus,\n      outcome: null,\n      callStatus: null,\n      notes:\n        'Provider error. The lead was returned to the call queue.',\n      logFollowup: false\n    };\n  }\n\n  // ==========================================================\n  // OTRO ERROR\n  // ==========================================================\n  else {\n    const exhausted =\n      attempts >= MAX_ATTEMPTS;\n\n    r = {\n      status: exhausted\n        ? 'CLOSED'\n        : 'UNREACHABLE',\n\n      stage: exhausted\n        ? 'UNRESPONSIVE'\n        : null,\n\n      attempts,\n      nextFollowUpAt: null,\n\n      last_call_status:\n        sipCode\n          ? 'SIP_' + sipCode\n          : 'OTHER_ERROR',\n\n      outcome: 'WRONG_NUMBER',\n      callStatus: 'FAILED',\n\n      notes: exhausted\n        ? (\n            `Call failed — attempt ${attempts}/${MAX_ATTEMPTS} — ` +\n            `maximum call attempts reached.`\n          )\n        : (\n            `Call failed or unreachable: ` +\n            message.slice(0, 150)\n          ),\n\n      logFollowup: true\n    };\n  }\n\n  console.log(\n    '📞 Asterisk —',\n    lead.lead_id,\n    '| HTTP',\n    httpStatus,\n    '| attempt',\n    attempts,\n    '| →',\n    r.status,\n    r.stage\n      ? '| stage ' + r.stage\n      : '',\n    '| next:',\n    r.nextFollowUpAt\n  );\n\n  return {\n    json: {\n      provider: 'asterisk',\n      lead_id: lead.lead_id,\n      country: lead.country,\n      elevenlabs_call_id:\n        conversationId,\n      last_call_time:\n        nowDate.toISOString(),\n      ...r\n    }\n  };\n});\n\nif (providerFails > 0) {\n  console.error(\n    `🚨 ElevenLabs: ${providerFails}/${items.length} ` +\n    `llamadas fallaron por problema del proveedor.`\n  );\n}\n\nreturn out;"},"id":"6f449e72-b772-42ed-841e-c55c16053181","name":"🔍 Classify Dial Result (Asterisk)3","type":"n8n-nodes-base.code","typeVersion":2,"position":[-15712,992]},{"parameters":{"jsCode":"const BASE = 'https://lead-studio-9gnl.onrender.com/api';\nconst TOKEN = $('🔐 Login LeadStudio3').first().json.accessToken;\nconst self = this;\n\nasync function api(method, path, opts = {}) {\n  try {\n    const r = await self.helpers.httpRequest({\n      method,\n      url: BASE + path,\n      qs: opts.qs,\n      body: opts.body,\n      json: true,\n      headers: {\n        Authorization: 'Bearer ' + TOKEN,\n        'Content-Type': 'application/json'\n      },\n      returnFullResponse: true,\n      ignoreHttpStatusErrors: true,\n      timeout: 20000\n    });\n\n    return {\n      ok:\n        r.statusCode >= 200 &&\n        r.statusCode < 300,\n      status: r.statusCode,\n      body: r.body || {}\n    };\n  } catch (e) {\n    return {\n      ok: false,\n      status: 0,\n      body: {\n        error: String(\n          e.message || e\n        )\n      }\n    };\n  }\n}\n\n// ============================================================================\n// 🏁 GUARDAR RESULTADO (ASTERISK)\n//\n// 1. POST followup.\n//    LeadStudio incrementa attempts.\n//\n// 2. PATCH status.\n//\n// 3. Si Classify pidió stage (UNRESPONSIVE),\n//    PATCH stage por separado.\n//\n// Se separa status de stage para no poner en riesgo\n// el cierre del lead si el stage fuera rechazado.\n// ============================================================================\n\nconst out = [];\nlet fails = 0;\n\nfor (const item of $input.all()) {\n  const j = item.json || {};\n\n  if (!j.lead_id) {\n    console.error(\n      '❌ Asterisk: item sin lead_id'\n    );\n    continue;\n  }\n\n  // ------------------------------------------------------------\n  // FOLLOWUP\n  // ------------------------------------------------------------\n  let fu = null;\n\n  if (j.logFollowup) {\n    const fuBody = {\n      type: 'CALL',\n      outcome: j.outcome,\n      callStatus: j.callStatus,\n      durationSeconds: 0,\n      notes: j.notes\n    };\n\n    if (j.nextFollowUpAt) {\n      fuBody.nextActionAt =\n        j.nextFollowUpAt;\n    }\n\n    fu = await api(\n      'POST',\n      `/leads/${j.lead_id}/followups`,\n      {\n        body: fuBody\n      }\n    );\n\n    if (!fu.ok) {\n      console.error(\n        `⚠️ Followup falló ${j.lead_id} ` +\n        `HTTP ${fu.status}`,\n        JSON.stringify(\n          fu.body\n        ).slice(0, 200)\n      );\n    }\n  }\n\n  // ------------------------------------------------------------\n  // STATUS\n  // ------------------------------------------------------------\n  let r = await api(\n    'PATCH',\n    `/leads/${j.lead_id}`,\n    {\n      body: {\n        status: j.status\n      }\n    }\n  );\n\n  if (!r.ok) {\n    r = await api(\n      'PATCH',\n      `/leads/${j.lead_id}`,\n      {\n        body: {\n          status: j.status\n        }\n      }\n    );\n  }\n\n  if (!r.ok) {\n    fails++;\n\n    console.error(\n      `❌ PATCH status falló 2 veces ${j.lead_id} ` +\n      `HTTP ${r.status}`,\n      JSON.stringify(\n        r.body\n      ).slice(0, 200)\n    );\n  }\n\n  // ------------------------------------------------------------\n  // STAGE (UNRESPONSIVE)\n  // Solo cuando Classify lo solicita.\n  // ------------------------------------------------------------\n  let stageResult = null;\n\n  if (\n    r.ok &&\n    j.stage\n  ) {\n    stageResult = await api(\n      'PATCH',\n      `/leads/${j.lead_id}`,\n      {\n        body: {\n          stage: j.stage\n        }\n      }\n    );\n\n    if (!stageResult.ok) {\n      // El status CLOSED ya quedó aplicado.\n      // Por eso no existe riesgo de otra llamada.\n      console.error(\n        `⚠️ Stage ${j.stage} falló para ${j.lead_id} ` +\n        `HTTP ${stageResult.status}. ` +\n        `El status ${j.status} sí quedó aplicado.`\n      );\n    }\n  }\n\n  const followupId =\n    fu &&\n    fu.ok &&\n    fu.body &&\n    fu.body.followUp\n      ? fu.body.followUp.id\n      : null;\n\n  out.push({\n    json: {\n      ...j,\n\n      patch_ok: r.ok,\n      patch_http: r.status,\n\n      stage_requested:\n        j.stage || null,\n\n      stage_ok:\n        stageResult\n          ? stageResult.ok\n          : null,\n\n      stage_http:\n        stageResult\n          ? stageResult.status\n          : null,\n\n      followup_ok:\n        fu\n          ? fu.ok\n          : null,\n\n      followup_id:\n        followupId\n    }\n  });\n}\n\nconsole.log(\n  `🏁 Asterisk: ${out.length} guardados | ` +\n  `${fails} PATCH fallidos`\n);\n\nreturn out;"},"id":"e42ee5b6-f2e1-43cc-a907-cb3d82477dcf","name":"🏁 Guardar Resultado (Asterisk)1","type":"n8n-nodes-base.code","typeVersion":2,"position":[-15472,992]},{"parameters":{"conditions":{"options":{"caseSensitive":true,"leftValue":"","typeValidation":"loose","version":2},"conditions":[{"id":"19137c5d-05f8-4e90-b6dc-c7e8e634506e","leftValue":"={{ $('⚙️ Calcular Providers Activos3').first().json.stringee_enabled }}","rightValue":true,"operator":{"type":"boolean","operation":"true","singleValue":true}}],"combinator":"and"},"options":{}},"id":"713ab525-aba6-4a02-a037-ad0a6f3b7670","name":"🔀 Stringee Habilitado?3","type":"n8n-nodes-base.if","typeVersion":2.2,"position":[-16432,1744]},{"parameters":{"jsCode":"console.log('⏸️ Stringee DESACTIVADO por wf2_provider_config — ciclo omitido');\nreturn [{ json: { skipped: true, provider: 'stringee', at: new Date().toISOString() } }];\n"},"id":"5e7efc91-0062-4ca7-b810-52081edad65b","name":"⏸️ Stringee Desactivado (log)3","type":"n8n-nodes-base.code","typeVersion":2,"position":[-16192,1904]},{"parameters":{"jsCode":"const BASE = 'https://lead-studio-9gnl.onrender.com/api';\nconst TOKEN = $('🔐 Login LeadStudio3').first().json.accessToken;\nconst self = this;\n\nasync function api(method, path, opts = {}) {\n  try {\n    const r = await self.helpers.httpRequest({\n      method,\n      url: BASE + path,\n      qs: opts.qs,\n      body: opts.body,\n      json: true,\n      headers: {\n        Authorization: 'Bearer ' + TOKEN,\n        'Content-Type': 'application/json'\n      },\n      returnFullResponse: true,\n      ignoreHttpStatusErrors: true,\n      timeout: 20000\n    });\n\n    return {\n      ok: r.statusCode >= 200 && r.statusCode < 300,\n      status: r.statusCode,\n      body: r.body || {}\n    };\n  } catch (e) {\n    return {\n      ok: false,\n      status: 0,\n      body: {\n        error: String(e.message || e)\n      }\n    };\n  }\n}\n\n// ============================================================================\n// 📥 FETCH + LOCK (STRINGEE)\n//\n// Regla:\n// 3 ciclos x 3 intentos = máximo 9.\n//\n// attempts 0-8  -> puede ir al worker.\n// attempts >= 9 -> NO va al worker.\n//                  status CLOSED.\n//                  stage UNRESPONSIVE.\n// ============================================================================\n\nconst MAX_ATTEMPTS = 9;\n\nconst COUNTRIES = [\n  {\n    key: 'india',\n    dialCode: '91',\n    prefix: '+91',\n    batchSize: 5,\n\n    lines: [\n      '917971730907',\n      '917944413269',\n      '917944413268',\n      '917971731010',\n      '917943609115'\n    ],\n\n    fromEnd: true,\n    minDigits: 10,\n    maxDigits: 10,\n    language: 'hi',\n\n    agent_id:\n      'agent_5701kramx550e3qs2tm11661b48p',\n\n    agent_phone_number_id: ''\n  }\n];\n\nconst FETCH_MULT = 3;\n\nfunction normalizePhone(raw, prefix) {\n  let p = String(raw || '')\n    .replace(/[^0-9+]/g, '');\n\n  if (!p) return '';\n\n  if (p.startsWith('+')) {\n    return p;\n  }\n\n  const digits =\n    prefix.replace('+', '');\n\n  if (\n    p.startsWith(digits) &&\n    p.length > digits.length + 6\n  ) {\n    return '+' + p;\n  }\n\n  return prefix + p;\n}\n\nfunction safeAttempts(value) {\n  const n = Number(value);\n\n  if (!Number.isFinite(n) || n < 0) {\n    return 0;\n  }\n\n  return Math.trunc(n);\n}\n\nasync function closeExhaustedLead(\n  leadId,\n  attempts,\n  country\n) {\n  // Primero cerrar.\n  const close = await api(\n    'PATCH',\n    `/leads/${leadId}`,\n    {\n      body: {\n        status: 'CLOSED'\n      }\n    }\n  );\n\n  if (!close.ok) {\n    console.error(\n      `🚨 Stringee ${country}: no se pudo cerrar ${leadId} ` +\n      `con ${attempts} intentos. HTTP ${close.status}. ` +\n      `Por seguridad NO se despacha.`\n    );\n\n    return {\n      closed: false,\n      lost: false\n    };\n  }\n\n  // Después mover el stage a UNRESPONSIVE.\n  const lost = await api(\n    'PATCH',\n    `/leads/${leadId}`,\n    {\n      body: {\n        stage: 'UNRESPONSIVE'\n      }\n    }\n  );\n\n  if (!lost.ok) {\n    console.error(\n      `⚠️ Stringee ${country}: ${leadId} quedó CLOSED, ` +\n      `pero stage UNRESPONSIVE falló HTTP ${lost.status}.`\n    );\n  }\n\n  console.log(\n    `⛔ Stringee ${country}: ${leadId} reached ` +\n    `${attempts}/${MAX_ATTEMPTS} attempts → no dispatch`\n  );\n\n  return {\n    closed: true,\n    lost: lost.ok\n  };\n}\n\nconst out = [];\n\nfor (const c of COUNTRIES) {\n  const limit = Math.min(\n    200,\n    c.batchSize * FETCH_MULT\n  );\n\n  let offset = 0;\n\n  if (c.fromEnd) {\n    const t = await api(\n      'GET',\n      '/leads',\n      {\n        qs: {\n          status: 'NOT_CONTACTED',\n          dialCode: c.dialCode,\n          limit: 1,\n          offset: 0\n        }\n      }\n    );\n\n    offset = t.ok\n      ? Math.max(\n          0,\n          Number(t.body.total || 0) - limit\n        )\n      : 0;\n  }\n\n  const r = await api(\n    'GET',\n    '/leads',\n    {\n      qs: {\n        status: 'NOT_CONTACTED',\n        dialCode: c.dialCode,\n        limit,\n        offset\n      }\n    }\n  );\n\n  if (!r.ok) {\n    console.error(\n      `❌ Stringee ${c.key}: GET /leads falló HTTP ${r.status}`,\n      JSON.stringify(r.body).slice(0, 300)\n    );\n\n    continue;\n  }\n\n  const leads = r.body.leads || [];\n\n  const totalDisponibles =\n    Number(r.body.total || 0);\n\n  let taken = 0;\n  let invalid = 0;\n  let lockFail = 0;\n  let exhausted = 0;\n\n  for (const l of leads) {\n    if (taken >= c.batchSize) break;\n\n    if (!l || !l.id) continue;\n\n    if (\n      String(l.status || '').toUpperCase() !==\n      'NOT_CONTACTED'\n    ) {\n      continue;\n    }\n\n    const currentAttempts =\n      safeAttempts(l.attempts);\n\n    // ==========================================================\n    // HARD LIMIT\n    // No permitir que un lead con 9+ attempts llegue al worker.\n    // ==========================================================\n    if (\n      currentAttempts >=\n      MAX_ATTEMPTS\n    ) {\n      await closeExhaustedLead(\n        l.id,\n        currentAttempts,\n        c.key\n      );\n\n      exhausted++;\n      continue;\n    }\n\n    if (l.doNotCall) {\n      await api(\n        'PATCH',\n        `/leads/${l.id}`,\n        {\n          body: {\n            status: 'CLOSED'\n          }\n        }\n      );\n\n      invalid++;\n      continue;\n    }\n\n    const phone =\n      normalizePhone(\n        l.phone,\n        c.prefix\n      );\n\n    const national =\n      phone.slice(\n        c.prefix.length\n      );\n\n    const validPhone =\n      /^\\+[1-9]\\d{7,14}$/.test(phone) &&\n      phone.startsWith(c.prefix) &&\n      national.length >= c.minDigits &&\n      national.length <= c.maxDigits;\n\n    if (!validPhone) {\n      await api(\n        'PATCH',\n        `/leads/${l.id}`,\n        {\n          body: {\n            status: 'UNREACHABLE'\n          }\n        }\n      );\n\n      console.log(\n        `🚫 ${c.key}: teléfono inválido '${l.phone}' ` +\n        `→ UNREACHABLE (${l.id})`\n      );\n\n      invalid++;\n      continue;\n    }\n\n    // Lock antes de llamar.\n    const lock = await api(\n      'PATCH',\n      `/leads/${l.id}`,\n      {\n        body: {\n          status: 'ATTEMPTING'\n        }\n      }\n    );\n\n    if (!lock.ok) {\n      lockFail++;\n\n      console.error(\n        `🔒❌ ${c.key}: no se pudo bloquear ` +\n        `${l.id} HTTP ${lock.status}`\n      );\n\n      continue;\n    }\n\n    out.push({\n      json: {\n        provider: 'stringee',\n\n        lead_id: l.id,\n\n        full_name:\n          String(l.name || '').trim() ||\n          'User',\n\n        phone,\n\n        country: c.key,\n\n        language:\n          String(\n            l.language ||\n            c.language\n          )\n            .trim()\n            .toLowerCase(),\n\n        call_attempts:\n          currentAttempts,\n\n        _agent_id:\n          c.agent_id,\n\n        _agent_phone_number_id:\n          c.agent_phone_number_id,\n\n        _from_number:\n          c.lines\n            ? c.lines[\n                taken %\n                c.lines.length\n              ]\n            : (\n                c.from_number ||\n                ''\n              )\n      }\n    });\n\n    taken++;\n  }\n\n  const msg =\n    `📥 Stringee ${c.key}: ` +\n    `${totalDisponibles} NOT_CONTACTED | ` +\n    `${leads.length} leídos | ` +\n    `${taken} bloqueados | ` +\n    `${exhausted} agotaron ${MAX_ATTEMPTS} intentos | ` +\n    `${invalid} inválidos | ` +\n    `${lockFail} lock fallidos`;\n\n  if (\n    taken === 0 &&\n    totalDisponibles > 0\n  ) {\n    console.error(\n      '🚨 Hay leads disponibles pero 0 llegaron al batch — ' +\n      msg\n    );\n  } else {\n    console.log(msg);\n  }\n}\n\nreturn out;"},"id":"808b54bb-38a4-4658-a249-15f039af8832","name":"📥 Fetch + Lock (Stringee)1","type":"n8n-nodes-base.code","typeVersion":2,"position":[-16192,1712]},{"parameters":{"method":"POST","url":"http://172.18.0.1:8091/call","sendHeaders":true,"headerParameters":{"parameters":[{"name":"Content-Type","value":"application/json"}]},"sendBody":true,"specifyBody":"json","jsonBody":"={\n  \"lead_id\": \"{{ $json.lead_id }}\",\n  \"phone\": \"{{ $json.phone.replace(/^\\+/, '') }}\",\n  \"full_name\": {{ JSON.stringify($json.full_name) }},\n  \"country\": \"{{ $json.country }}\",\n  \"language\": \"{{ $json.language || 'hi' }}\",\n  \"is_followup\": \"{{ $json.call_attempts > 0 ? 'true' : 'false' }}\",\n  \"call_attempts\": {{ Number($json.call_attempts || 0) + 1 }},\n  \"from_number\": \"{{ $json._from_number }}\",\n  \"agent_id\": \"agent_5701kramx550e3qs2tm11661b48p\",\n  \"callback_url\": \"https://landmarket-n8n.dhsoig.easypanel.host/webhook/stringee-worker-callback\"\n}","options":{"response":{"response":{"fullResponse":true,"neverError":true,"responseFormat":"json"}},"timeout":45000}},"id":"a762d64a-bd2c-4575-b866-845e070b6ec1","name":"📞 POST → Stringee Worker3","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[-15952,1712],"onError":"continueRegularOutput"},{"parameters":{"jsCode":"// ============================================================================\n// 🔍 CLASSIFY RESULT (STRINGEE)\n//\n// IMPORTANTE:\n// Este nodo NO conoce todavía el resultado final de la llamada.\n//\n// El worker solamente confirma que la llamada fue despachada.\n// El resultado final llega por webhook a WF9.\n//\n// Por esa razón:\n// - NO marcar LOST aquí.\n// - NO crear followup aquí.\n// - NO asumir NO_ANSWER.\n// ============================================================================\n\nconst items = $input.all();\n\nconst src =\n  $('📥 Fetch + Lock (Stringee)1').all();\n\nconst now =\n  new Date().toISOString();\n\nfunction safeAttempts(value) {\n  const n = Number(value);\n\n  if (!Number.isFinite(n) || n < 0) {\n    return 0;\n  }\n\n  return Math.trunc(n);\n}\n\nfunction pickLead(item, i) {\n  let idx = i;\n\n  const p = item.pairedItem;\n\n  if (\n    p !== undefined &&\n    p !== null\n  ) {\n    const pi = Array.isArray(p)\n      ? p[0]\n      : p;\n\n    if (typeof pi === 'number') {\n      idx = pi;\n    } else if (\n      pi &&\n      typeof pi.item === 'number'\n    ) {\n      idx = pi.item;\n    }\n  }\n\n  return (\n    src[idx] ||\n    src[i] ||\n    src[0]\n  ).json;\n}\n\nreturn items.map(\n  (item, i) => {\n    const lead =\n      pickLead(item, i);\n\n    const resp =\n      item.json || {};\n\n    const statusCode =\n      Number(\n        resp.statusCode ?? 0\n      );\n\n    const body =\n      (\n        resp.body !== undefined\n          ? resp.body\n          : resp\n      ) || {};\n\n    const jobId =\n      String(\n        body.job_id ||\n        body.jobId ||\n        ''\n      );\n\n    const attempts =\n      safeAttempts(\n        lead.call_attempts\n      ) + 1;\n\n    let r;\n\n    // Worker aceptó la llamada.\n    if (\n      statusCode >= 200 &&\n      statusCode < 300 &&\n      body.ok === true &&\n      jobId\n    ) {\n      r = {\n        status: 'ATTEMPTING',\n        attempts,\n        last_call_status:\n          'DISPATCHED',\n\n        // English-only en caso de que en el futuro\n        // esta nota llegue al CRM.\n        notes:\n          'Stringee call dispatched. Worker job: ' +\n          jobId\n      };\n    }\n\n    // Error temporal del proveedor.\n    else if (\n      statusCode === 0 ||\n      statusCode === 429 ||\n      statusCode >= 500\n    ) {\n      r = {\n        status: 'NOT_CONTACTED',\n        attempts: null,\n        last_call_status:\n          'WORKER_ERROR_' +\n          statusCode,\n\n        notes:\n          'Stringee worker unavailable. ' +\n          'The lead was returned to the call queue.'\n      };\n\n      console.error(\n        `🚨 Stringee worker no responde ` +\n        `(HTTP ${statusCode}).`\n      );\n    }\n\n    // Error definitivo al intentar despachar.\n    else {\n      r = {\n        status: 'UNREACHABLE',\n        attempts,\n        last_call_status:\n          statusCode >= 400\n            ? 'HTTP_' + statusCode\n            : 'NO_JOB_ID',\n\n        notes:\n          'Stringee call dispatch failed: ' +\n          JSON.stringify(body)\n            .slice(0, 200)\n      };\n    }\n\n    console.log(\n      '📞 Stringee —',\n      lead.lead_id,\n      '| HTTP',\n      statusCode,\n      '| attempt',\n      attempts,\n      '| →',\n      r.status,\n      '| job:',\n      jobId\n    );\n\n    return {\n      json: {\n        provider: 'stringee',\n\n        lead_id:\n          lead.lead_id,\n\n        country:\n          lead.country,\n\n        job_id:\n          jobId || null,\n\n        last_call_time:\n          now,\n\n        nextFollowUpAt:\n          null,\n\n        outcome:\n          null,\n\n        callStatus:\n          null,\n\n        logFollowup:\n          false,\n\n        ...r\n      }\n    };\n  }\n);"},"id":"aa00cdc3-ea2c-4c0c-b7b8-c7a7ceea25f1","name":"🔍 Classify Result (Stringee)3","type":"n8n-nodes-base.code","typeVersion":2,"position":[-15712,1712]},{"parameters":{"jsCode":"const BASE =\n  'https://lead-studio-9gnl.onrender.com/api';\n\nconst TOKEN =\n  $('🔐 Login LeadStudio3')\n    .first()\n    .json\n    .accessToken;\n\nconst self = this;\n\nasync function api(\n  method,\n  path,\n  opts = {}\n) {\n  try {\n    const r =\n      await self.helpers.httpRequest({\n        method,\n\n        url:\n          BASE +\n          path,\n\n        qs:\n          opts.qs,\n\n        body:\n          opts.body,\n\n        json:\n          true,\n\n        headers: {\n          Authorization:\n            'Bearer ' +\n            TOKEN,\n\n          'Content-Type':\n            'application/json'\n        },\n\n        returnFullResponse:\n          true,\n\n        ignoreHttpStatusErrors:\n          true,\n\n        timeout:\n          20000\n      });\n\n    return {\n      ok:\n        r.statusCode >= 200 &&\n        r.statusCode < 300,\n\n      status:\n        r.statusCode,\n\n      body:\n        r.body || {}\n    };\n  } catch (e) {\n    return {\n      ok: false,\n\n      status: 0,\n\n      body: {\n        error:\n          String(\n            e.message ||\n            e\n          )\n      }\n    };\n  }\n}\n\n// ============================================================================\n// 🏁 GUARDAR RESULTADO (STRINGEE)\n//\n// Este nodo solamente guarda el estado del DISPATCH.\n//\n// NO crea el resultado final.\n// NO incrementa manualmente attempts.\n// NO crea un NO_ANSWER falso.\n//\n// El resultado final pertenece a WF9.\n// ============================================================================\n\nconst out = [];\n\nlet fails = 0;\n\nfor (\n  const item\n  of $input.all()\n) {\n  const j =\n    item.json || {};\n\n  if (!j.lead_id) {\n    console.error(\n      '❌ Stringee: item sin lead_id'\n    );\n\n    continue;\n  }\n\n  // En esta rama normalmente logFollowup=false.\n  // Se mantiene la compatibilidad por seguridad.\n  let fu = null;\n\n  if (j.logFollowup) {\n    const fuBody = {\n      type: 'CALL',\n      outcome: j.outcome,\n      callStatus: j.callStatus,\n      durationSeconds: 0,\n      notes: j.notes\n    };\n\n    if (\n      j.nextFollowUpAt\n    ) {\n      fuBody.nextActionAt =\n        j.nextFollowUpAt;\n    }\n\n    fu = await api(\n      'POST',\n      `/leads/${j.lead_id}/followups`,\n      {\n        body:\n          fuBody\n      }\n    );\n\n    if (!fu.ok) {\n      console.error(\n        `⚠️ Followup falló ${j.lead_id} ` +\n        `HTTP ${fu.status}`,\n        JSON.stringify(\n          fu.body\n        ).slice(\n          0,\n          200\n        )\n      );\n    }\n  }\n\n  // Solo status, igual que la arquitectura actual.\n  let r =\n    await api(\n      'PATCH',\n      `/leads/${j.lead_id}`,\n      {\n        body: {\n          status:\n            j.status\n        }\n      }\n    );\n\n  if (!r.ok) {\n    r =\n      await api(\n        'PATCH',\n        `/leads/${j.lead_id}`,\n        {\n          body: {\n            status:\n              j.status\n          }\n        }\n      );\n  }\n\n  if (!r.ok) {\n    fails++;\n\n    console.error(\n      `❌ PATCH falló 2 veces ${j.lead_id} ` +\n      `HTTP ${r.status}`,\n      JSON.stringify(\n        r.body\n      ).slice(\n        0,\n        200\n      )\n    );\n  }\n\n  const followupId =\n    fu &&\n    fu.ok &&\n    fu.body &&\n    fu.body.followUp\n      ? fu.body.followUp.id\n      : null;\n\n  out.push({\n    json: {\n      ...j,\n\n      patch_ok:\n        r.ok,\n\n      patch_http:\n        r.status,\n\n      followup_ok:\n        fu\n          ? fu.ok\n          : null,\n\n      followup_id:\n        followupId\n    }\n  });\n}\n\nconsole.log(\n  `🏁 Stringee: ${out.length} guardados | ` +\n  `${fails} PATCH fallidos`\n);\n\nreturn out;"},"id":"7df28be5-645a-4fce-871c-3dc2acd9f4ea","name":"🏁 Guardar Resultado (Stringee)1","type":"n8n-nodes-base.code","typeVersion":2,"position":[-15472,1712]},{"parameters":{"rule":{"interval":[{"field":"minutes"}]}},"id":"28e99bf6-d27b-4fd2-938a-9f6a1672c30b","name":"⏰ Trigger Mantenimiento (cada 5 min)1","type":"n8n-nodes-base.scheduleTrigger","typeVersion":1.3,"position":[-17632,2176]},{"parameters":{"jsCode":"// ============================================================================\n// 🧹 MANTENIMIENTO (cada 5 min) — red de seguridad para que NUNCA quede un lead\n// muerto, SIN romper el límite de 9 intentos. Hace su propio login y usa\n// GET /leads con paginación real.\n//  0. Lee de MySQL (nodo anterior) qué leads tienen un job Stringee SIN resolver\n//     y qué reintentos retuvo WF9 (next_retry_at). Si esa consulta falló, NO se\n//     libera ni se reactiva nada (fail-safe) y se avisa con 🚨.\n//  1. ATTEMPTING colgado > STALE_MIN:\n//       - con job Stringee sin resolver  -> NO se toca (WF9 lo va a cerrar)\n//       - attempts >= 9                  -> CLOSED + stage UNRESPONSIVE\n//       - resto                          -> NO_ANSWER (no suma intento)\n//  2. NO_ANSWER:\n//       - attempts >= 9 -> CLOSED + stage UNRESPONSIVE (nunca vuelve a la cola)\n//       - vencido       -> NOT_CONTACTED (vuelve a la cola)\n//     \"Vencido\" usa, en este orden: el reintento retenido por WF9 (next_retry_at),\n//     lead.nextFollowUpAt si fue fijado después del último cambio del lead, o\n//     (si falta / quedó viejo) la última actualización + el ciclo 3x3 según attempts.\n//     (LeadStudio ignora PATCH nextFollowUpAt — sólo lo fija nextActionAt del\n//     POST /followups — por eso este nodo ya no lo intenta escribir.)\n//  3. Reporta cuántos NOT_CONTACTED hay por país (salud)\n// Primero se juntan TODOS los IDs y recién después se hacen los PATCH, para que\n// la paginación por offset no se corra al ir cambiando estados.\n// ============================================================================\nconst BASE = 'https://lead-studio-9gnl.onrender.com/api';\nconst DIAL_CODES = [{ key: 'india', dialCode: '91' }, { key: 'nepal', dialCode: '977' }];\nconst STALE_MIN = 30;\nconst MAX_ATTEMPTS = 9;\nconst EXHAUSTED_STAGE = 'UNRESPONSIVE';\nconst MAX_PAGES = 25;     // hasta 5.000 leads por status/país por corrida\nconst self = this;\nlet TOKEN = '';\n\nasync function api(method, path, opts = {}) {\n  try {\n    const r = await self.helpers.httpRequest({\n      method, url: BASE + path, qs: opts.qs, body: opts.body, json: true,\n      headers: Object.assign({ 'Content-Type': 'application/json' }, TOKEN ? { Authorization: 'Bearer ' + TOKEN } : {}),\n      returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 20000\n    });\n    return { ok: r.statusCode >= 200 && r.statusCode < 300, status: r.statusCode, body: r.body || {} };\n  } catch (e) { return { ok: false, status: 0, body: { error: String(e.message || e) } }; }\n}\n\n// ---------- 0) Estado de eventos (MySQL) ----------\nconst dbRows = $input.all().map(i => i.json || {});\nconst dbOk = dbRows.some(r => r.kind === 'ok') && !dbRows.some(r => r.error || r.message && !r.kind);\nconst unresolved = new Map();   // lead_id -> { n, sinceMs }\nconst holds = new Map();        // lead_id -> { holdMs, setMs }\nlet stuckFailed = 0;\nfor (const r of dbRows) {\n  if (r.kind === 'unresolved' && r.lead_id) unresolved.set(String(r.lead_id), { n: Number(r.n) || 0, sinceMs: Number(r.set_ms) || 0 });\n  if (r.kind === 'hold' && r.lead_id && Number(r.hold_ms) > 0) {\n    const prev = holds.get(String(r.lead_id));\n    if (!prev || Number(r.hold_ms) > prev.holdMs) holds.set(String(r.lead_id), { holdMs: Number(r.hold_ms), setMs: Number(r.set_ms) || 0 });\n  }\n  if (r.kind === 'stuck') stuckFailed = Number(r.n) || 0;\n}\nif (!dbOk) {\n  console.error('🚨 Mantenimiento: la consulta a wf_call_events falló. Fail-safe: no se libera ni se reactiva ningún lead en esta corrida.', JSON.stringify(dbRows).slice(0, 300));\n}\nif (stuckFailed > 0) console.error(`🚨 wf_call_events: ${stuckFailed} eventos FAILED con 5+ errores — revisar WF9`);\n\nconst login = await api('POST', '/auth/login', { body: { email: 'ai@leadstudio.com', password: 'Admin@123' } });\nif (!login.ok || !login.body.accessToken) {\n  console.error('❌ Mantenimiento: login falló', login.status, JSON.stringify(login.body).slice(0, 200));\n  return [{ json: { error: true, step: 'login', status: login.status } }];\n}\nTOKEN = login.body.accessToken;\n\nasync function listAll(status, dialCode) {\n  const all = []; let offset = 0;\n  for (let p = 0; p < MAX_PAGES; p++) {\n    const r = await api('GET', '/leads', { qs: { status, dialCode, limit: 200, offset } });\n    if (!r.ok) { console.error(`❌ GET /leads ${status} ${dialCode} HTTP ${r.status}`); break; }\n    const leads = r.body.leads || [];\n    all.push(...leads);\n    offset += leads.length;\n    if (leads.length < 200 || offset >= Number(r.body.total || 0)) break;\n  }\n  return all;\n}\n// Cada op es una lista de PATCH secuenciales para el mismo lead (status primero, stage después)\nasync function patchMany(list) {\n  let ok = 0, fail = 0;\n  for (let i = 0; i < list.length; i += 10) {\n    const chunk = list.slice(i, i + 10);\n    const res = await Promise.all(chunk.map(async x => {\n      for (const body of x.bodies) {\n        let r = await api('PATCH', `/leads/${x.id}`, { body });\n        if (!r.ok && r.status === 400 && 'nextFollowUpAt' in body) {\n          // si el backend no acepta nextFollowUpAt=null, el cierre se aplica igual sin ese campo\n          const b2 = Object.assign({}, body); delete b2.nextFollowUpAt;\n          r = await api('PATCH', `/leads/${x.id}`, { body: b2 });\n        }\n        if (!r.ok) { console.error(`⚠️ PATCH ${x.id} ${JSON.stringify(body)} HTTP ${r.status}`); return false; }\n      }\n      return true;\n    }));\n    res.forEach(r => r ? ok++ : fail++);\n  }\n  return { ok, fail };\n}\nfunction safeAttempts(v) { const n = Number(v); return Number.isFinite(n) && n >= 0 ? Math.trunc(n) : 0; }\nfunction msOf(v) { const t = v ? new Date(v).getTime() : NaN; return Number.isFinite(t) ? t : null; }\nfunction addBusinessDays(d, days) {\n  const r = new Date(d.getTime()); let added = 0;\n  while (added < days) { r.setDate(r.getDate() + 1); const wd = r.getDay(); if (wd !== 0 && wd !== 6) added++; }\n  return r;\n}\n// Próximo intento según el ciclo 3x3 (mismo cálculo que WF2 / WF9)\nfunction policyDue(attempts, baseMs) {\n  const a = Math.max(1, attempts);\n  const pos = ((a - 1) % 3) + 1;\n  const cycle = Math.ceil(a / 3);\n  const base = new Date(baseMs);\n  if (pos === 1) return baseMs + 2 * 3600000;\n  if (pos === 2) return baseMs + 3 * 3600000;\n  return addBusinessDays(base, cycle === 1 ? 2 : 3).getTime();\n}\nconst closeOp = id => ({ id, bodies: [{ status: 'CLOSED', nextFollowUpAt: null }, { stage: EXHAUSTED_STAGE }] });\n\nconst now = new Date();\nconst nowMs = now.getTime();\nconst summary = {};\nfor (const c of DIAL_CODES) {\n  // 1) ATTEMPTING colgados\n  const attempting = await listAll('ATTEMPTING', c.dialCode);\n  const stale = attempting.filter(l => l.status === 'ATTEMPTING' && l.updatedAt &&\n    (nowMs - new Date(l.updatedAt).getTime()) > STALE_MIN * 60000);\n  const staleOps = [];\n  let heldByJob = 0, closedAttempting = 0;\n  if (dbOk) {\n    for (const l of stale) {\n      const u = unresolved.get(String(l.id));\n      if (u && u.n > 0) {\n        heldByJob++;\n        if (u.sinceMs && nowMs - u.sinceMs > 2 * 3600000) console.error(`🚨 ${c.key}: ${l.id} lleva >2 h en ATTEMPTING con job Stringee sin resolver`);\n        continue;\n      }\n      if (safeAttempts(l.attempts) >= MAX_ATTEMPTS) { staleOps.push(closeOp(l.id)); closedAttempting++; continue; }\n      staleOps.push({ id: l.id, bodies: [{ status: 'NO_ANSWER' }] });\n    }\n  }\n  const staleRes = await patchMany(staleOps);\n\n  // 2) NO_ANSWER: agotados -> CLOSED/UNRESPONSIVE ; vencidos -> NOT_CONTACTED\n  const noAnswer = await listAll('NO_ANSWER', c.dialCode);\n  const exhaustedOps = [];\n  const dueOps = [];\n  let heldByRetry = 0, recomputed = 0;\n  for (const l of noAnswer) {\n    if (l.status !== 'NO_ANSWER') continue;\n    const attempts = safeAttempts(l.attempts);\n    if (attempts >= MAX_ATTEMPTS) { exhaustedOps.push(closeOp(l.id)); continue; }\n    if (!dbOk) continue; // sin datos de reintentos retenidos no se reactiva nada\n    if (l.doNotCall) continue;\n    const upd = msOf(l.updatedAt) || nowMs;\n    const h = holds.get(String(l.id));\n    let dueMs;\n    if (h && h.holdMs && (!h.setMs || upd <= h.setMs + 120000)) {\n      dueMs = h.holdMs;                        // reintento retenido por WF9 (corrección de buzón)\n      if (dueMs > nowMs) heldByRetry++;\n    } else {\n      const nf = msOf(l.nextFollowUpAt);\n      if (nf && nf >= upd - 10 * 60000) {\n        dueMs = nf;                            // fijado por nextActionAt en la última llamada\n      } else {\n        dueMs = policyDue(attempts, upd);      // faltante o viejo: se recalcula (no se reactiva en falso)\n        recomputed++;\n      }\n    }\n    if (dueMs <= nowMs) dueOps.push({ id: l.id, bodies: [{ status: 'NOT_CONTACTED' }] });\n  }\n  const exhaustedRes = await patchMany(exhaustedOps);\n  const dueRes = await patchMany(dueOps);\n\n  // 3) Salud\n  const h = await api('GET', '/leads', { qs: { status: 'NOT_CONTACTED', dialCode: c.dialCode, limit: 1, offset: 0 } });\n  const disponibles = h.ok ? Number(h.body.total || 0) : null;\n\n  summary[c.key] = {\n    attempting_total: attempting.length,\n    attempting_colgados: stale.length,\n    attempting_retenidos_por_job: heldByJob,\n    attempting_liberados: staleRes.ok,\n    attempting_cerrados_agotados: closedAttempting,\n    no_answer_total: noAnswer.length,\n    no_answer_cerrados_agotados: exhaustedRes.ok,\n    no_answer_reactivados: dueRes.ok,\n    no_answer_retenidos_wf9: heldByRetry,\n    no_answer_vencimiento_recalculado: recomputed,\n    patch_fallidos: staleRes.fail + exhaustedRes.fail + dueRes.fail,\n    not_contacted_disponibles: disponibles,\n    db_ok: dbOk\n  };\n  console.log(`🧹 ${c.key}:`, JSON.stringify(summary[c.key]));\n  if (disponibles === 0) console.error(`🚨 ${c.key}: 0 leads NOT_CONTACTED — el dialer no tiene a quién llamar`);\n}\nreturn [{ json: { ran_at: now.toISOString(), ...summary } }];\n"},"id":"1d2fed1f-9580-421e-824d-27bfdb648bf7","name":"🧹 Mantenimiento Leads (reactivar + liberar)1","type":"n8n-nodes-base.code","typeVersion":2,"position":[-17152,2176]},{"parameters":{"content":"### 📞 WF2 UNIFICADO v2 — Asterisk + Stringee (rediseño 24/09/2026)\n\n**Incidente 24/09:** `/leads/queue` devuelve siempre la misma ventana, con follow-ups vencidos (ATTEMPTING/CONTACTED) primero. El filtro exigía NOT_CONTACTED → los descartaba, nunca se tocaban y **bloquearon la cabeza de la cola** con 17k leads disponibles detrás. ~4h sin llamadas.\n\n**Reglas del v2 (no romper):**\n1. Leer SIEMPRE `GET /leads?status=NOT_CONTACTED&dialCode=X` — NO `/leads/queue`.\n2. Lock `PATCH → ATTEMPTING` ANTES de llamar; solo se llama si el lock OK.\n3. Lead inválido (teléfono / doNotCall) se saca del pool → nunca tapa la cola.\n4. Error del proveedor (key, créditos, 429, 5xx, worker caído) → lead vuelve a NOT_CONTACTED sin sumar intento.\n5. 🧹 Mantenimiento cada 5 min: ATTEMPTING > 30 min → NO_ANSWER, salvo job Stringee sin resolver (no se toca) o attempts ≥ 9 (CLOSED + UNRESPONSIVE). NO_ANSWER vencido → NOT_CONTACTED; con attempts ≥ 9 → CLOSED + UNRESPONSIVE, nunca vuelve a la cola. Si MySQL falla, no libera nada.\n7. Asterisk toma India desde el principio de la lista y Stringee desde el final → no se pisan.\n6. Logs con 🚨 = revisar ya (0 al batch habiendo disponibles, proveedor caído, 0 disponibles).\n\n`/leads/queue` solo acepta `limit` (1–200) y `dialCode`. `/leads` acepta `status`, `dialCode`, `limit`, `offset`.\n8. Stringee: cada job despachado queda en `wf_call_events` (ledger) y el worker avisa a WF9 por `callback_url`; WF9 crea la Activity. Agotamiento (9 intentos) = CLOSED + stage UNRESPONSIVE (no LOST).","height":520,"width":620,"color":4},"id":"971583f0-78b8-48a9-aadd-ee31d1c086ac","name":"🧭 Nota — Diseño v","type":"n8n-nodes-base.stickyNote","typeVersion":1,"position":[-17696,752]},{"parameters":{"method":"POST","url":"https://lead-studio-9gnl.onrender.com/api/auth/login","sendBody":true,"specifyBody":"json","jsonBody":"={\n  \"email\": \"ai@leadstudio.com\",\n  \"password\": \"Admin@123\"\n}","options":{"response":{"response":{"neverError":true,"responseFormat":"json"}},"timeout":15000}},"id":"e1211e59-6bdd-4cf8-a5ee-35d2515d698f","name":"🔐 Login LeadStudio3","type":"n8n-nodes-base.httpRequest","typeVersion":4.2,"position":[-16912,1312],"retryOnFail":true,"maxTries":3,"waitBetweenTries":2000},{"parameters":{"jsCode":"// ============================================================================\n// 🧾 BUILD DEFERRED LEDGER (ASTERISK) — llamada Asterisk CONTESTADA.\n//\n// Por qué existe: LeadStudio fija durationSeconds en el POST /followups y NO lo deja\n// editar después (PATCH /followups/{id} -> 400 \"Nothing to update\"). Este nodo corre\n// cuando la llamada acaba de ser contestada (la API de ElevenLabs responde al contestar,\n// no al colgar), o sea antes de conocer el billsec real. Por eso la Activity de una\n// llamada contestada la crea WF9 al TERMINAR la llamada (con CDR.billsec).\n//\n// Aquí sólo se deja un registro durable en wf_call_events con la MISMA clave que usan el\n// webhook y el polling de ElevenLabs (elevenlabs:<conversation_id>): mismo evento, sin\n// duplicados. dispatched_at es la marca \"esta llamada la creará WF9\".\n// Luego se CONFIRMA con un SELECT: 🏁 Guardar Resultado (Asterisk) sólo difiere la Activity\n// de las llamadas confirmadas; si el registro falla, crea la Activity como antes (nunca se\n// pierde una llamada).\n// Sin llamadas contestadas en este lote -> consulta vacía (SELECT 1).\n// Horas en UTC explícito.\n// ============================================================================\nconst CONV_RE = /^conv_[A-Za-z0-9]{8,64}$/;\nfunction q(v) {\n  if (v === null || v === undefined || v === '') return 'NULL';\n  if (typeof v === 'number') return Number.isFinite(v) ? String(Math.trunc(v)) : 'NULL';\n  return \"'\" + String(v).replace(/\\u0000/g, '').replace(/[\\r\\n]+/g, ' ').replace(/\\$/g, '').replace(/\\\\/g, '\\\\\\\\').replace(/'/g, \"''\")\n    .replace(/\\{\\{/g, '{ {').replace(/\\}\\}/g, '} }') + \"'\";\n}\nfunction dt(v) {\n  const t = v ? new Date(v).getTime() : NaN;\n  return Number.isFinite(t) ? \"'\" + new Date(t).toISOString().replace('T', ' ').replace('Z', '') + \"'\" : 'UTC_TIMESTAMP(3)';\n}\nconst locked = $('📥 Fetch + Lock (Asterisk)').all().map(i => i.json || {});\nconst phoneOf = id => { const l = locked.find(x => x.lead_id === id); return l ? String(l.phone || '').replace(/[^0-9+]/g, '').slice(0, 32) : null; };\nconst rows = [];\nconst keys = [];\nfor (const it of $input.all()) {\n  const j = it.json || {};\n  if (String(j.outcome || '').toUpperCase() !== 'CONNECTED' || String(j.callStatus || '').toUpperCase() !== 'ANSWERED') continue;\n  const conv = String(j.elevenlabs_call_id || '');\n  if (!CONV_RE.test(conv) || !j.lead_id) continue;\n  const att = Number(j.attempts);\n  const key = 'elevenlabs:' + conv;\n  if (keys.includes(q(key))) continue;\n  keys.push(q(key));\n  rows.push('(' + [q(key), q('elevenlabs'), q('asterisk'), q(conv), q(String(j.lead_id).slice(0, 64)), q(phoneOf(j.lead_id)),\n    q(Number.isInteger(att) && att >= 1 && att <= 99 ? att : null), dt(j.last_call_time), dt(j.last_call_time), 'UTC_TIMESTAMP(3)', q('RECEIVED'),\n    'UTC_TIMESTAMP(3) + INTERVAL 3 MINUTE', q(JSON.stringify({ via: 'wf2_asterisk_answered_deferred' }))].join(', ') + ')');\n}\nif (!rows.length) return [{ json: { ledger_rows: 0, ledger_sql: 'SELECT 1 AS noop' } }];\nconst ledger_sql = 'INSERT INTO wf_call_events (event_key, source, provider, external_id, lead_id, phone, call_attempts, ' +\n  'event_at, dispatched_at, first_seen_at, state, next_attempt_at, payload) VALUES ' + rows.join(', ') +\n  ' ON DUPLICATE KEY UPDATE provider = VALUES(provider), lead_id = COALESCE(lead_id, VALUES(lead_id)), ' +\n  'phone = COALESCE(phone, VALUES(phone)), call_attempts = COALESCE(call_attempts, VALUES(call_attempts)), ' +\n  'event_at = COALESCE(event_at, VALUES(event_at)), dispatched_at = COALESCE(dispatched_at, VALUES(dispatched_at))' +\n  '; SELECT event_key FROM wf_call_events WHERE dispatched_at IS NOT NULL AND event_key IN (' + keys.join(', ') + ')';\nconsole.log(`🧾 Asterisk contestadas: ${rows.length} llamada(s) registradas para que WF9 cree la Activity al terminar`);\nreturn [{ json: { ledger_rows: rows.length, ledger_sql } }];\n"},"name":"🧾 Build Deferred Ledger (Asterisk)","type":"n8n-nodes-base.code","typeVersion":2,"position":[-21040,1312],"id":"8c7e1352-d085-5a4d-a4a1-242c07c8a622"},{"parameters":{"operation":"executeQuery","query":"{{ $json.ledger_sql }}","options":{}},"name":"💾 Ledger Deferred (Asterisk)","type":"n8n-nodes-base.mySql","typeVersion":2.4,"position":[-20800,1312],"credentials":{"mySql":{"id":"4NiWyzzJ4JbMkIjT","name":"MySQL account"}},"alwaysOutputData":true,"retryOnFail":true,"maxTries":2,"waitBetweenTries":1000,"onError":"continueRegularOutput","id":"52694054-f399-502c-a65f-bdf40e54a631"}]$WF2N$::json,
